  Voice_100335_AwakerVoiceContent = {
    Text = "なあ、守秘者。大学の墓地に連れてってくれないか？あそこに眠る偉大な魂と触れ合えば、とびきりのインスピレーションが湧いてきそうなんだ。分かってる、もう死体を掘り出して観察したりしないからさ……約束する。"
  },
  Voice_100335_AwakerVoiceTitle = {
