  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "俺は光と影、俺は色彩、俺は……絵画そのものだ！"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "んー？あんたの心は、見たこともない色で輝いてるな……これはいったい……なんなんだ？"
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_100338_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "完璧な黒の絵の具だな！昔、融蝕の粘液で描いた絵は、全部消えちまった。原初宇宙から来たこの色は、すべてを飲み込み、誰の記憶にも残らない……最高だろ、そんなの！"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "雑談・危機について"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "もっと……もっと近くで見せてくれ！この光と影、この色彩、この形……これに比べたら、今まで描いて来た絵なんてゴミ同然だ……"
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_100340_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "ドゥルセイン様はよく、自分の料理は芸術だとか語ってるけど、食事と芸術はまったく別もんだろ？貴重な創作時間を死体の処理に費やして、やっと完成させたところで、結局は食って終わり。そんなのは、芸術への冒涜だ！"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_100342_AwakerVoiceContent = {
