  },
  Voice_100342_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "最低なモデルだ。"
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "くっ、また駄作だ……インスピレーションを探しに行くしかないな。墓地か、それとも処刑場か……"
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "彫刻は堅苦しくて好きじゃないが、サンガーって美術家の作品だけは、こう、彫刻の枠に収まらないというか、ヤバいんだよ……ああいうのを天才って言うんだろうな！"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "雑談・サンガーについて"
  },
  Voice_100345_UnlockDesc = {
    Text = "覚醒体「サンガー」獲得で解放"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "この絵を見てくれ、守秘者！あんたの肖像画だ！死体を食らう姿が、最高に魅力的だろ？俺の絵は誰もが理解できるもんじゃない。けどあんたなら、この狂気の美しさが分かるよな？それだけでいいんだ、俺は。それで十分なんだ。"
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_100346_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "この絵を買いたいって……本気か？あ、ありがとな、守秘者！俺の絵を理解してくれる人間は、マジで少ないからさ……"
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_100347_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "なあ、守秘者。またモデルになってくれないか？あんたの中に見えた光景を思い出すと、他のモデルじゃ時間の無駄に思えるんだよ。"
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "この絵の中で、新たな誕生を見届けろ！"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "霊知啓発"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "この生き生きとした線を見ろ！"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "この筆が生み出すものは、きっと誰もが驚く傑作になる！"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "これは！新しい絵の具か……よし、一番ふさわしい場所に塗ってやる！"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "ここは本当にインスピレーションが湧いてくるな！また新作が生まれそうだ。なあ、守秘者。俺のアトリエを見に来ないか？遠慮するなって、さあさあ！"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_100353_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "いい、いいぞ！血にまみれた勝利！なんて絶妙な構図なんだ！"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_100355_AwakerVoiceContent = {
    Text = "うわっ！"
  },
  Voice_100355_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "おっ、守秘者か！そこに座ってくれ！モデルってのは骨が折れる仕事だからな。安心しろって、最高傑作を仕上げてやるよ！"
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_100356_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "本当はさ、芸術家ってのは、他人の目を気にせず、作品だけを見つめるべきなんだ。でも、俺にはできない。筆を握ったその日から、ずっと願ってるんだ。真の美しさってやつを、大勢に見せてやりたいって。"
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_100357_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "ここにいると、美術学院にいた頃を思い出すんだ。教授や生徒のほとんどは芸術を理解しない凡人ばっかだったけど、何人かは俺の絵の真価に気づいてくれてさ。"
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "この野蛮なショーが、斬新な芸術を生み出すんだ！"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "俺のパレットが！"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "苦痛もまた芸術だ……"
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "ああ！見えてきた……深淵の底に潜む眼なき瞳、宇宙の究極図……もう少しだ、守秘者。もうすぐ傑作が完成する……！"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_100362_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "この筆は、俺の脛骨で作ったんだ。こっちのパレットの絵の具は、二十以上の街をまわって、墓地から集めてきた。そして、この貴重な皮のキャンバス！なあ、守秘者。頼む、これで俺の肖像画を描いてくれ！いや、技術なんてなくていい。心と心が響き合えば、きっと想像もつかない傑作が生まれるはずだ！"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_100363_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "俺は光と影、俺は色彩、俺は……絵画そのものだ！"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "この色はどうだ！"
  },
  Voice_100365_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_100366_AwakerVoiceContent = {
    Text = "芸術の本質は、狂気だ……！"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "ん？その部分をクローズアップして描いてみろって？へえ……考えたこともなかったぜ！天才的な発想だな！"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_100368_AwakerVoiceContent = {
    Text = "危ない！"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "芸術の本質は、狂気だ……！"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "俺のパレットが！"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "おお！この流れるような顎のライン、澄んだ瞳、完璧なプロポーション！そして、星空のように果てしない心……あ、ごほん、俺は画家のピックマンだ。あんたを描かせてもらいたいんだが、頼めるか？"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "召喚"},
  Voice_100372_AwakerVoiceContent = {
    Text = "俺が信じる芸術は、狂ってて、ざわついてて、不安定な衝動の塊だ。でも、ハムリンの音楽はまったく違う。墓石のように規則的で、なのになぜか、その整然とした音符の中に、宇宙に渦巻く混沌が見えてくるんだ。"
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "雑談・ハムリンについて"
  },
  Voice_100372_UnlockDesc = {
    Text = "覚醒体「ハムリン」獲得で解放"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "見てくれ、守秘者！キャンバスに刻まれた永遠の、狂気に満ちた光景を！魂を揺さぶる、この絶望的な美しさを！究極の狂気と苦痛の中でこそ、真の芸術は咲き誇るんだ！"
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_100373_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "あっ、悪い！つい見惚れてた……！あんたの中にすごいもんが見えてさ。深淵より恐ろしく、ゾッとするくらい魅力的な……"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_100374_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "どうして人間はグールになろうとしないんだ？この血まみれで狂気的な美しさを見ろよ！屋敷に引きこもって無為に生きるより、ずっと刺激的だろ？"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_100376_AwakerVoiceContent = {Text = "ハッ！"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "罪を懲らしめん！"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "罪を懲らしめん！"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "特殊スキル・二"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "彼女の盗みの腕は確かに一級品よ。でも、淑女たるわたくしに、そんな卑怯な真似は必要ないわ。わたくしが欲しいものはみんな『進んで』差し出してくれるんだもの！"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "雑談・ジェンキンについて"
  },
  Voice_117791_UnlockDesc = {
    Text = "覚醒体「ジェンキン」獲得で解放"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "あははははっ！ミサゴのキャンディはぜーんぶ、魔女たるこのわたくしが頂戴するわ！何をぐずぐずしているの、下僕！？今すぐロンディニウム中のお菓子屋を征服しに行くわよ！"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_117792_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "ええ！？くれないの！？……なら！本気で取りに行くわよ！"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "ねぇ、このキャンディのフィリング、一体どうやって中に入れたのかしら？隙間も針穴も見当たらないわ。こんなお菓子を発明した者を、ミサゴのレストランにスカウトして、毎日新作スイーツを作らせるのはどうかしら？"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "魔女を怒らせたわねー！"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "以前のわたくしは、キャンディなんてケーキと比べたら安っぽくて、エレガントじゃないって思ってたわ。でも、このカラフルな包みに秘められた可能性……正直、見くびってたわ！ケーキと違って保存が利くし、部屋にたっぷりストックを……あっ！……そうだわ！この壁も床も天井も、ぜーんぶキャンディで埋め尽くしましょ！"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "新しいキャンディを見つけたの？どれどれ……\n……何よ、この指輪キャンディ！卵サイズのダイヤなんて笑っちゃ……ちょ、ちょっと！わたくしに指輪を贈るなんて……どういうつもり！？ちゃんと説明しなさいよ……"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_117797_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "魔女には黒猫の使い魔がつきものらしいわね。でも、学校のあの野良猫を連れ歩くなんて淑女として面目丸つぶれだわ……んーー……決めた！\nあなた、猫耳カチューシャを付けなさい！わたくしの使い魔に任命してあげるわ。"
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_117798_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "抵抗しても無駄よ！"
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "んべー！"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "……魔女って、ほんとにいるのかしら？ひとけのない森に一人で住んでるっていうけど、食事とか洗濯とか、それにおやつの準備は誰がするの？アフタヌーンティーを楽しめない人生なんて……考えただけでぞっとするわ。"
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_117801_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "魔女、参上～！"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "あら、チョコレートも持ってるの？ぜんぶ寄こしなさい！何よ、文句あるわけ？あなたのものはわたくしのもの、当然のことでしょう？"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_117803_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "一番好きなキャンディ？うーん……ヘーゼルナッツのプラリネは後味が最高だし、キャラメルチョコもたまらないし、フルーツ入りのソフトキャンディも食感が楽しいし、水飴は蜂蜜のようにキレイで、くるくるして遊べるから……ああもう！選べるわけないじゃない！どうせカボチャバスケットは沢山あるんだから、ぜ～んぶもらっていくわ！"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_117804_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "わたくしの夢は、世界中のキャンディを食べ尽くすこと！数え切れないほどある未知のキャンディを思うと、朝起きるのが楽しみで仕方ないわ。\nんん？……ケーキ？それはもう一つの夢ね。"
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_117805_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "あの人、見ためは子供でも、とっくに墓場に入ってる歳だからかしら……キャンディどころか、生者が喜ぶものには、一切興味を示さないのよ……だから、彼の分のキャンディは全部わたくしが預かってあげる！なんたって、キャンディを一番楽しめるのは、わたくしだもの！"
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "雑談・トゥルーについて"
  },
  Voice_117806_UnlockDesc = {
    Text = "覚醒体「トゥルー」獲得で解放"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "もしわたくしが魔女になるなら、ぜったい豪華な宮殿に住むわ！にぎやかなお城で、最高のシェフを１０人も揃えて、毎日違うケーキとキャンディを作らせるの……えぇ？それは魔女じゃなくてプリンセス？いいじゃないプリンセス魔女になったって！"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_117807_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "ねえ！急いでいろんな味の歯磨き粉を用意して！……別に、キャンディを食べ過ぎたわけじゃないの……！虫歯なんて……ありえないわ！ただ……夜、寝るときに、ほんのちょっと……ほんのちょっとだけ……歯が……ちくちくするの……"
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "キャンディについて"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "ミサゴのレストランって規則が気に入らないのよね。でも、シェフのお菓子作りの腕は……\nはむ……まあ及第点かしら。"
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "この世なんて、暗くて不愉快なことだらけよ。世界の終わりに悩むより、キャンディをいっぱい食べる方がよっぽど有意義ね。"
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_117811_AwakerVoiceContent = {
    Text = "いたっ！"
  },
  Voice_117811_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "今はもうウール絨毯も、黒真珠ネックレスも、シルクパジャマもないけど……目覚めたらキャンディに囲まれてて、カボチャバスケットがいつでも満杯で……こういう生活こそ、幸せっていうのかしら…………ちょっと！なにニヤニヤして……調子に乗らないでよね！？あんたなんかこれからもずーっと、ずーーっと、わたくしの下僕なんだから！"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_117812_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "ミサゴも無駄なことをするわね！わたくしのキャンディ狩りを邪魔するなんて！結局、こうしてわたくしの口に入るんだから……ふふっ！"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "はあ？わたくしのキャンディが欲しい？ふんっ、あなたの態度次第では、恵んであげなくもないわよ？ほら、『魔女様』って呼んでみなさい！"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "だれが強盗ですってぇ？ふんっ、これは淑女として当然の権利なんだから！"
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "正義のキャンディ魔女、参上！すべての失われたキャンディよ、あるべき場所に戻りなさい！"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "もう！もうっ！なんて、けちんぼなの！後で覚えてなさいよ～！！"
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "あのネズミは堂々とキャンディをかっぱらってるのに、どうして淑女のわたくしはダメなの！？これは明白な差別よ！不敬だわ！"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "ええ！？くれないの！？……なら！本気で取りに行くわよ！"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "キャンディーをあげる！"
  },
  Voice_117820_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_117821_AwakerVoiceContent = {
    Text = "レストランの給仕に比べたら、やっぱりあなたの方がずっと気が利くわね。わたくし専用のキャンディを用意してあるなんて、さすがわたくしの下僕ね！"
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_117821_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "んべー！"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "ひどーい！"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "邪魔しないで！あなたはわたくしの下僕なんでしょう？だったら、わたくしの代わりにキャンディを全部奪って……じゃなくて、持ってくるべきでしょう！？"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "動かないで！わたくしはキャンディ魔女よ！\nさあ、大人しくキャンディを寄こしなさい！\nさもないと……どうなってもしらないわよ？"
  },
  Voice_117825_AwakerVoiceTitle = {Text = "召喚"},
  Voice_117826_AwakerVoiceContent = {
    Text = "ふわふわ、カリカリ、トロトロ、パリパリ……ミルク味、フルーツ味、ナッツ味、チョコ味！\nああ、わたくしの知らないキャンディが、まだこんなにあるなんて！……決めた！毎週『幽世祭』を開催するわよ！\nだめだなんて言わせないから！"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_117827_AwakerVoiceContent = {Text = "あっ！"},
  Voice_117827_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "偉大な魔女は必ず勝利するわ！キャンディの神に祝福されたわたくしが、すべてのキャンディを守るのよ！あはははは！"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "抵抗しても無駄よ！"
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "すべてのキャンディは、わたくしのものになる運命なのよ！"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "あの子って、怖いくらい従順よね。キャンディが欲しいって言ったら、自分のぶんも一つ残らず全部くれるんだから……べ、別に気にしてないわよ！ただ、その心意気に免じて、慈悲深い魔女としてお裾分けしてあげただけよ！"
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "雑談・リリーについて"
  },
  Voice_117831_UnlockDesc = {
    Text = "覚醒体「リリー」獲得で解放"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "魔女を怒らせたわねー！"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "怒ったわ！"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "すべてのキャンディは、わたくしのものになる運命なのよ！"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "……わ、わたあめを、焼いて食べるですって！？熱くてベタベタで、まずそうなんだけど……？……そこまで言うなら、ひと口だけ味見してあげるわ。嘘だったら許さないわよ…………んっ！？なにこのサクほろ感……美味しいじゃない！"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_117835_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "虚妄も、倒錯も、運命のままに！"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "虚妄も、倒錯も、運命のままに！"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "本当のあたしが怖くないのは、本物の恐怖を知っているから……？何それ、ズルくない？でも、まあ……あなたに興味は湧いたかも。"
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_123312_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "ねえ……あなたの目に、世界はどう映ってるの？恐怖の限界はどこにあると思う？違うよ、あなたの口から聞きたいんじゃない。狂気も、恐怖も、死も……全部、あなたと一緒に感じたいの。決めた！この好奇心が満たされるまで、あたしはあなたの傍を離れないから。"
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_123313_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "手に負えない狂人、か……その通りかもね。ここはあたしがいた世界じゃない。くだらない法律も、掟もない。だから、どう振る舞おうがあたしの自由。つ・ま・り……暴走した狂人に噛まれたくなかったら、せいぜい気をつけるんだよ、守秘者さん。"
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_123314_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "身体の調子もメンタルの状況も怖いから、一度じっくり話がしたいって？別にいいけど、今すぐ始めてくれる？退屈なことはさっさと終わらせたいんだよね。"
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_123315_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "「思っていることを素直に言え」？「『正しく』答えようとするな」？……あちゃ～、バレちゃってたか。それじゃあ、あたしの本性と向き合う覚悟はできてるんだよね？"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_123316_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "てりゃーッ！はい、生首一丁。"
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "とっておきのやつで、イカせてあげる――シャイニング☆トルネーーード！！"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "なんで、あたしなの……"
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "シャイニング☆クラッシュ!!！"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "この恐怖に歪められた世界を救いたいの？いいね、大胆で面白い死に方じゃん。あなたがどこまで行けるか、あたしが見届けてあげるよ。"
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "やっほ～、かわい子ちゃんたち～！すぐに斧をお見舞いしてあげるから、一列に並んでね～！"
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "（期待を込めて）ねえねえ、守秘者！今、光が見えなかった！？今度こそイケるんじゃない！？……（懐かしそうに）調査団のみんなはどうしてるんだろ。（軽い文句）あたしの仕事、全部ほったらかしにされてたりして。残業は御免だよ……"
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_123776_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "この儀式が終われば帰れるの？ほんと？一応、これで何度目になるかはわかってるんだよね？……ま、いっか。試すだけタダだし。"
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_123777_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "きゃははっ！やっぱ退屈な日常なんかより、アドレナリンドッパドパなこの瞬間のほうがあたしに向いてるぅ～っ！"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_123779_AwakerVoiceContent = {Text = "ハ！"},
  Voice_123779_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_123780_AwakerVoiceContent = {
    Text = "なんで、あたしなの……"
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "シャイニング☆スーパーノヴァ！発射！！"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "とっておきのやつで、イカせてあげる――シャイニング☆トルネーーード！！"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "なんだろう、この感覚……まるで霧に包まれてるみたい。霧の中にいたあの子たちを思い出すなぁ。いいストレスの捌け口だったのに、残念。"
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_123783_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "「嫌い」？そんな言い方はしないよ。ただ、つまんない会議とか、人付き合いとか、世の中の価値観とかが、ぜ～んぶ消えちゃえばいいのにって思ってるだけ。"
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "そうそう、これこれ……「本当の自分」に、どんどん近づいてる気がする。"
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "失敗かぁ……だろうね。人生は山あり谷ありって言うけど、谷の方が全然多いもん。いい加減慣れないと……でも、その……ありがとう。あたしのために、色々と頑張ってくれて。"
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_123786_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "霧の災厄にしろ、融食のことにしろ、あたしが知ってることは限られてる。でも、そこが逆に魅力的だと思わない？"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "雑談・危機について"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "はいは～い、ムシェットだよ。調査団所属の……っと、そういえばもう違うんだっけ。それじゃあ、改めまして――あたしはムシェット。ただの可憐な女の子で～す！"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "召喚"},
  Voice_123789_AwakerVoiceContent = {
    Text = "どけぇっ！"
  },
  Voice_123789_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "人間の居住地が近いせいで、どこもかしこも退屈な大人ばっかり……ねえ、学園を山奥とか、誰もいないところに移そうと思ったことはないの？"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(痛呼)"},
  Voice_123791_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "異世界を彷徨うのって、なんかクセになるんだよね～！強い覚醒体に怖い融食、そして未知の神までいるんだもん！これが平凡な社会から抜け出せた、カイホー感っていうの？もう、最高っ！"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "えっ、もう終わり？これからだったのに～！じゃあ、もう一回だけ斬らせてよ！誰でもいいから、早く早くっ！"
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(痛呼)"},
  Voice_123794_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "まぁ、人生に失敗の1回や2回……あってたまるかぁ～！！おまえら全員、首洗って待ってな！！"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "何、何？任務？……あ～、そっちかぁ。もう、次からは挨拶とかいいから。あたしとあなたの仲でしょ？「社交辞令」とか、息苦しいだけだもん。"
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "誰かのために自分を犠牲にするとか、バカげてるし、正直腹が立つ。そんなことを彼に命じる資格なんて、神にだってないのに。"
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "雑談・サルバドルについて"
  },
  Voice_123797_UnlockDesc = {
    Text = "覚醒体「サルバドル」獲得で解放"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "へえ、やるじゃん。"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "ふぅ、やっと本性が出せる……満足するまで、た～っぷり遊んであげるよ。"
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "霊知啓発"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "ねぇ、まだ終わらないの？ここのセイロンティーとアンダルシアのチュロスも悪かないんだけど、レイヴンローグ煮魚と淹れたてのヘーゼルナッツカヴァ茶が恋しくてしょうがないんだよ。"
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_123800_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "鍛えてくれるのはありがたいけど、あたしがいつか暴走したらどうする気？……な～んてね。ははっ、冗談だってば。"
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "実は、しばらくこの世界に残るのも悪くないかな～って思ってたんだよね。ここで見たもの、聞いたものをぜ～んぶ覚えて、向こうのみんなへの土産話にするんだ。名付けて、『ムシェットの異世界冒険記』！どう？最高でしょっ？"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_123802_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "あの子かぁ……うん、確かにかわいいと思う。大学の野良猫と追いかけっこしたり、ケンカしてる時とか、特に。"
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "雑談・マーフィーについて"
  },
  Voice_123803_UnlockDesc = {
    Text = "覚醒体「マーフィー」獲得で解放"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "これっぽちの力じゃ、元の世界には戻れないけど……まぁ、成長は成長ってことで。"
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "ああ、メイドね。あたしもやったことあるよ。今度、あたしが開発した掃除機で戦う方法を伝授してあげよっかな！"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "雑談・カレンについて"
  },
  Voice_123805_UnlockDesc = {
    Text = "覚醒体「カレン」獲得で解放"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "きゃははっ！やっぱ退屈な日常なんかより、アドレナリンドッパドパなこの瞬間のほうがあたしに向いてるぅ～っ！"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "あの世へいってら～。"
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "特殊スキル・二"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "はいはい、順番は守ろうね～。"
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "消滅せよ！"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "無心なり、不乱なり。盲にて聴き、唖にて従え。塵世万事は枷と知れ！"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "無心なり、不乱なり。盲にて聴き、唖にて従え。塵世万事は枷と知れ！"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "あやつらの頭の中が空っぽなのは、どうしてかって？\nんー、きっと、生まれた時からそうなのでしょうね。"
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "怒ることなかれ、恨むことなかれ。万象空無であると知れ。"
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "なんとお優しい。\nもっとからかいたくなってしまいますわ。"
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_126951_AwakerVoiceContent = {Text = "ああ！"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "あなた様がわらわに望むのは更なる美しさでございますか？\nそれとも更なる恐ろしさでございますか？"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "快楽の中から生まれたその姫は、金糸で刺繍されたドレスをまとっていた。\n象牙のような美しい肌と、漂う甘い香りは、見る者を一瞬で虜にした。"
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_126953_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "信者たちが同じ芝居を繰り返すだけの遊びに、彼女はすぐに飽きてしまった。\n欲から生まれる愛、愛から生まれる欲にまみれ、喪失と裏切りに苦しむ。\nそんな彼らの愚かさや涙に、彼女はうんざりしたのです。"
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_126954_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "その目つき、イライラしますわ。"
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "マダム・レッドは、何度もサロンへ招待してくださいましたわね。\n異国のお菓子は、なかなか美味しかったですわ。ですけど……\n彼女のお邸では、お菓子と召使いは別物だってことを、もっと早く教えてほしかったですわ。"
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "雑談・ソレールについて"
  },
  Voice_126956_UnlockDesc = {
    Text = "覚醒体「ソレール」獲得で解放"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "愛しておられるのでしょう？ならどうして囲まれて怯えますの？\nお嫌いなのでしょう？ならどうして失って涙を流しますの？\nおやおや、わらわのことが怖くなりましたか？\n木蓮の香りが、理解できないほど甘ったるい匂いに変わってしまいましたか？"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_126958_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_126959_AwakerVoiceContent = {Text = "ウッ！"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "えっ？どうして彼女たちは脇の下にタトゥーを入れてるのか、ですって？\nおもしろい以外に何がありますの？"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "雑談・脹婦会について"
  },
  Voice_126961_AwakerVoiceContent = {Text = "ああ！"},
  Voice_126961_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "わらわが信者からの奉納品よりも望んでおりましたのは、まさにこれでございます。"
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "まずは身体、次に身なり、そしてそのモノたちは同じような二つの目を手に入れた……\n人の記憶に深く残るような、魂を抜かれるほどに美しい目――\nわらわと同じような目が。"
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_126964_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "退屈で死にそうですわ。なにか叶えたい夢はございませんか？\n実に残念ですわ。多くの人がつまらない目的のために剣を振るい、わらわに血肉を捧げているというのに……\nでも、あなた様なら……"
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_126965_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "脹婦会とはいったいどういう組織で、どうしてわらわにつきまとっているのかって？\n面白いことをお聞きになりますのね。\nあなた様はこれまで、思いが届かなかった人や、やりたくてもできなかったことはございますか？\nどうやらなさそうですわね。残念ですわ。\n絶望にゆがむあなた様のお顔は、きっと、至高の芸術に違いありませんわ。"
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_126966_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "……これ以上、同じことを繰り返すおつもりなら、わらわも何をするか分かりませんわよ。"
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "彼女の物語は、もうほとんど忘れてしまいました。\nただ言えるのは、それは楽しい物語であり、残忍な物語であったということ。\n『遺棄』と『応報』から始まり、最後は『犠牲』と『盲従』の物語でした。"
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_126968_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "さあ！痛みと恐怖の中で殺し合うがいい！"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "……なかなかやりますわね。"
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "誰もがこの扇の向こう側に愛する人の面影を見る。\nわらわは、弱き者に力を与えるのです。\n剣を振るう哀れで美しい姿を眺めるのが、わらわの喜び。\nですが、もし……もしあなた様もそうなってくれたら、それはわらわの至高の歓びとなるでしょう。"
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_126971_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "心配には及びません。あなた様はあの凡人たちとは違います。\nシーッ！後ろを見てはなりません。\nなにかが触れていることは気にせず――\nわらわの目だけを見てくださいませ。"
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_126972_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "ウフフッ！この姿を直視できますかしら？"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "霊知啓発"
  },
  Voice_126975_AwakerVoiceContent = {
    Text = "おだまりなさい。"
  },
  Voice_126975_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_126976_AwakerVoiceContent = {
    Text = "あらあら、またわらわの扇をそんなにお見つめになって！\nウフフッ、この扇の陰に誰の面影を見たいと願おうとも、わらわが叶えて差し上げますわ。さあ！もっとこちらへ――\nまあ！やめろですって？そんなかわいらしいお顔で、冷たいことをおっしゃるのね……"
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_126976_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "あなた様はこの不夢郷でいったい何を捜しにこられたのかしら？"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "怒ることなかれ、恨むことなかれ。万象空無であると知れ。"
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "無礼者！"
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_126980_AwakerVoiceContent = {Text = "ウッ！"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "わらわにも、こんなにかわいくて従順な娘がいましたのよ。\nですが美しい蕾には、棘が必要です。花瓶に挿して飾っておくことはできませんわ。"
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "雑談・リリーについて"
  },
  Voice_126981_UnlockDesc = {
    Text = "覚醒体「リリー」獲得で解放"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "カウンセリングルームで働かせてほしいと学園に申し出たのですが、断られました。\n何がいけないのか、まったく分かりませんわ！"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "いずれ全ては無に帰すのですから、もっと今を楽しみませんか？\nご安心ください。いつの日か、あなた様が抵抗できなくなっても、わらわはあなた様をそのモノたちに渡したりいたしません。"
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "雑談・危機について"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "気に障りますわ。"
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "珍しいお方ですわね。\n滅びゆくこの世界で、たわいもないことのために駆け回っていらっしゃるなんて。\nそんなあなた様が気になって仕方ありませんわ。"
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_126985_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "近付くでない！"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "わらわは不夢郷の主、徐と申します。\nもしあなた様の心の中に会いたいお方がおいでなら、わらわがこの扇を外して、あなた様にひと目、お見せしましょう。"
  },
  Voice_126988_AwakerVoiceTitle = {Text = "召喚"},
  Voice_127088_AwakerVoiceContent = {
    Text = "生き物の子どもというのは厄介ですわ。\nちっぽけで、弱くて、うるさい。そのくせ気付けば、周りを自分のいいように支配している。\n賑やかなのは好きですけど、こういう賑やかさは嫌いですわ。\n絶対にわらわに近付けないでくださいね。"
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "わらわにとってのジャスミンちゃんであり、いい子ちゃんであり、甘くてたまらない、わらわだけの『おままごと』……\nヤダ！わらわったら、何を言ってるのかしら！気にしないでくださいませ。"
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "磐竜国の伝説の中で、孔雀は美しくも獰猛な獣とされています。\n美しくて、獰猛。聞くだけで、胸が踊りますわ。\n醜くて優しいなんて、おもしろくもなんともありませんもの。"
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "食べろ食べろ、全部食べてしまえ"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "ブクブク！"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "コルちゃん、あたし、ごはん、一緒？一緒に、ごはん！"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_129653_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "モス！すごく強い！"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "深淵！螺旋！破壊！すべて——渦巻きになれ！"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_129656_AwakerVoiceContent = {
    Text = "イタッ！"
  },
  Voice_129656_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "あたしにさわる、ダメ！こわれる！"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_129657_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "貝がら、キラキラ！キラキラ、きれい！あげる！"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_129658_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "つめたい、こわい！モス、かくれる！"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "雑談・ドールについて"
  },
  Voice_129659_UnlockDesc = {
    Text = "覚醒体「ドール」獲得で解放"
  },
  Voice_129660_AwakerVoiceContent = {
    Text = "やったー！"
  },
  Voice_129660_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "かり、きらい！やっつける！モス、あいつら、やっつける！"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "たのしい！次！もっと！"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_129662_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "ナデナデ、いいよ！モスも、あなた、ナデナデ！"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "イ、イヤ！コルちゃん、モスがまもる！"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "雑談・危機について"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "もう一回？もう一回！"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "エヘヘ！モス！あそぶ！"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "霊知啓発"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "大波、ザブーン！"
  },
  Voice_129667_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_129668_AwakerVoiceContent = {Text = "エイ！"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_129669_AwakerVoiceContent = {
    Text = "イタッ！"
  },
  Voice_129669_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_129670_AwakerVoiceContent = {Text = "ウッ！"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "ぎしき！？一緒に、行く！"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_129671_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "うずまき！力！すごい！"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_129672_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_129673_AwakerVoiceContent = {Text = "ドン！"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_129674_AwakerVoiceContent = {
    Text = "いくぞ！"
  },
  Voice_129674_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "パチャパチャ！"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_129676_AwakerVoiceContent = {
    Text = "ケンカ！"
  },
  Voice_129676_AwakerVoiceTitle = {
    Text = "雑談・ゴリアテについて"
  },
  Voice_129676_UnlockDesc = {
    Text = "覚醒体「ゴリアテ」獲得で解放"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "見つけた！たくさん！キラキラ！"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_129677_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "深淵！螺旋！破壊！すべて——渦巻きになれ！"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_129679_AwakerVoiceContent = {
    Text = "ひゃっほー！"
  },
  Voice_129679_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_129680_AwakerVoiceContent = {Text = "ウッ！"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "モス！すごく強い！"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "食べろ食べろ、全部食べてしまえ"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "オウムガイ、ナウティラ、コルちゃん！キラキラ！"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "モス、弾薬装填！"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "スキル・二・装填一"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "モス、流す！"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "スキル・二・装填・II"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "だっこ！モス！大すき！"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_129686_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "コルちゃん、トモダチ！モス、ずっと一緒！"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "早く、早く！"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_129688_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "モス！コルちゃん！ずっと、一緒？ずっと！"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_129689_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "ザブーン！ザブーン！大波、ザブーン！"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_129690_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "トモダチ！いっぱい！すき！"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "モス！すごい！"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "ナウティラ、会いたい。ああ、ナウティラ、モス、ここ！モス、ここ！"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "雑談・ナウティラについて"
  },
  Voice_129693_UnlockDesc = {
    Text = "覚醒体「ナウティラ」獲得で解放"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "モス！強くなった！"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "あたし！モス！やっほー！"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "召喚"},
  Voice_130511_AwakerVoiceContent = {Text = "ふー"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "スキル・二・装填・三"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "誤りは修正せねばなりません。"
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "あなたがご覧になった悲劇は、数え切れない可能性のほんの一つにすぎません。運命の幕の向こう側にあるのは、真っ暗なステージ。光は消え、役者は去り、すべては混沌の深淵へと還る。ですが、そこで、すべてが終わるわけではありません。私には、再び光が灯る日まで、 この虎王の苦役に耐える覚悟があります。"
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "雑談·危機について"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "普通、人の運命というのは、糸によって導かれます。ですが、あなたの運命の台本は、私にも解読不能です。あなたがこの世界で、どんな即興劇を演じてくれるのか、とても楽しみですわ。"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "主演の人形よ、お前の舞台に上がるがいい。"
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_133724_AwakerVoiceContent = {Text = "ん？"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "すべては過去であり、すべては序章である。守秘者、あなたと私の新しい物語を綴るのは、他でもないあなた自身です。"
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_133725_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "喜劇がお好きなら、おすすめは『真夏の夜の夢』です。ウィットに富んだイタズラ好きの妖精、パックのジョークや妖精の笑い声の中に、運命がうっかり漏らした秘密の言葉が含まれていますから。"
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_133726_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "抗うことなかれ。"
  },
  Voice_133727_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_133728_AwakerVoiceContent = {
    Text = "紡輪よ、ここに回れ。"
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "運命に囚われし、哀れな者よ。己に定められし、判決を受けよ。"
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "どれほど優れた洞察力があっても、己の台本の中では、ただの不器用な役者にすぎません。運命の網を握っていても、最後にはその糸に縛られ、定められた境遇の中で、それぞれの道を歩くしかありません。ですが、決して徒労の追求をやめたりはいたしません。愚かと言われようと、妄想と言われようと、それが私であり、彼女ですから。"
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "雑談・タヴィについて"
  },
  Voice_133730_UnlockDesc = {
    Text = "覚醒体「タヴィ」獲得で解放"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "予想外の展開です。"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "ダメージ・一"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "最後までご観覧いだたき誠にありがとうございました。今後も皆様の期待に答えより一層感動的なお芝居をお届けできるよう、精進してまいります。"
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_133732_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "天才的な歌手ですわ。天から賜りし歌声は、透き通っていながら燃えるように熱く、まるで運命から生まれた声のようです。もしあの方を、私の劇場にお招きすることができれば、どんなにうるさい客でも、黙らせることができるでしょう。"
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "雑談・ティンクトについて"
  },
  Voice_133733_UnlockDesc = {
    Text = "覚醒体「ティンクト」獲得で解放"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "あなたと私の運命の糸はきつく絡まり合い 牢屋と道を織りなしています牢屋の縁も道の果ても見えませんそれがこの物語の一番の魅力です"
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_133734_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "運命の糸は垂らされたままです。"
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "彼女はよく、私の劇場に来てくださいます。ですが、彼女が劇場に来るのは、芝居のためではなく、 自分の格式を引き立たせるためようです。それにしても、あれだけの演技ができますのに、ずっと、ただの観客でいるのは、もったいないと感じます。彼女は暗い観客席ではなく、スポットライトのもとでこそ、花開く存在です。"
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "雑談・ソレールについて"
  },
  Voice_133736_UnlockDesc = {
    Text = "覚醒体「ソレール」獲得で解放"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "彼の奏でる旋律は素晴らしく、魂が震えました。そうだ。新しいお芝居に、運命をテーマにした公共曲を作ってもらえないか、頼んでみようかしら。"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "雑談・ハムリンについて"
  },
  Voice_133737_UnlockDesc = {
    Text = "覚醒体「ハムリン」獲得で解放"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "また一つ、幸せな物語の幕が降りました。"
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "私には見えます。無限に広がる運命の網の全貌が。"
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "もし、お許しいただけるなら、あなたと私だけの劇を作りたいですわ。観客もリハーサルも要ります。私はただあなたのスポットライトを浴びた時、私にも見えない運命の糸がどのように躍動するのかを見てみたいのです。"
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_133740_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "かわいそうなダンサーです。私は、この目で彼女のステップを見ました。あれは、破滅と隣り合わせの、あまりにも危険な美しさです。彼女が回転するたびに、緑の炎が燃え上がり、まるで運命の糸を焼き切ろうとしているようでした。ですが、残念ながら、結局、その糸が壮絶な最後を描き出すことになります。もしチャンスがあれば、彼女だけの舞踊劇を描いてみたいと思っています。"
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "雑談・リッツについて"
  },
  Voice_133741_UnlockDesc = {
    Text = "覚醒体「リッツ」獲得で解放"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "ここに紡ぎ、ここに計り、ここに判決を下す。"
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "怒りを鎮めたまえ。"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "また、一本の糸がはっきりと見えました。"
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "幕が上がり、今まさに運命の台本が開かれようとしています。あなたはどんな運命の奇跡を辿りたいですか？悲しい結末？それとも歓喜の序章？"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_133745_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "私は、運命の糸を紡ぐことに夢中です。繰り返される静かな引力の中で、全ての物語の始まりと終わりを見通し、その幕引きを見ていると、まるで運命を超越しているかのように感じられます。ですが結局、運命の網からは逃れられず、 ただ見ているだけの自分が、虚しくなるのです。そんな時、私は劇場に行きます。そして、自らが紡ぎながらも、経験することのない悲しみや喜びを演じるのです。"
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "雑談·好きなもの"
  },
  Voice_133747_AwakerVoiceContent = {
    Text = "うわっ！"
  },
  Voice_133747_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_133748_AwakerVoiceContent = {
    Text = "うふふ…"
  },
  Voice_133748_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "ここに紡ぎ、ここに計り、ここに判決を下す。"
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "運命のささやきが近づいてきました。"
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "劇場では、新たなロマンティックコメディーが上映されます。すでに運命の観客席で、あなたのために特別な席を取りました。さまざまな運命が織りなす長い夜に、私はここで待ち続けるのでしょう。あなたを導いてくれる、星の光が降り注ぐ時まで…"
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_133751_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "そんなにしつこく運命の糸をつつくなんて、ご自身の物語がずいぶんと気になるようですわね。"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "未来はすぐそこにあります。"
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "心をえぐるような悲劇を求めるなら、アンティゴネしかありません。神の世界と人の世の狭間で、彼女は運命で紡がれた糸の上を歩き、墓場の奥へと足を踏み入れる。逃れられない抑圧ゆえに、彼女の小さな体からほとばしる意志が、闇夜を照らす一筋の炎のように輝くのです。"
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_133754_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "先が見えない結末も、逃れる術のない因果の網も…"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "糸の上には、美しく変化する虹色の光があります。その光が広大な網になり、果てしない世界と無限の可能性を作り出し、最終的に、見たことがないほど美しい模様を織りなす。結局、神も凡人も、英雄も悪人も、その細い糸に操られ、運命に監視されながら、自分に与えられた道を進むしかないのです。"
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "雑談・ミサゴが大学について"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "まさか、こんな選択をするなんてあなたのお芝居に対する趣味はとても印象的ですね。"
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_133757_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "運命の意図は、 見えないところで繋がっています。その意図をかき乱したということは、私をも、かき乱したということになります。"
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_133758_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "変化のない型にはまったお芝居は、 見る気になれません。劇場に足を運ぶ意義は、その場限りの生きたステージを楽しむことにあります。もし、機械のように同じことを繰り返すだけなら、ステージは精巧な牢屋となり、感激はただの退屈な巡礼となるでしょう。たとえどんなに華やかでも、魂の宿らないステージを、あなたは見たいと思いますか?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "雑談·嫌いなもの"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "あなたが現れたことで、これまで私の手の中で、整然と流れていた運命の意図の軌跡に、見たことのない波紋が発生しました。"
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_133760_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "運命に囚われし、哀れな者よ。己に定められし、判決を受けよ。"
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "無限の糸の中にて、ただ1つの奇跡を織りなす。"
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "知恵の覚醒"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "誰もが己の因果を背負い、運命という名の舞台の上で、ただ静かに待ち続けているのです。喜びと悲しみの歯車がかみ合い、新たな物語が紡がれる、その開演の時よ。さあ、幕が開きました。守秘者、あなたと私の物語の始まりです。"
  },
  Voice_133763_AwakerVoiceTitle = {Text = "召喚"},
  Voice_133764_AwakerVoiceContent = {
    Text = "戦いが始まりました。あなたが演じるのは、網を破る英雄ですか?それとも運命に身を任せる脇役ですか?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "無駄な抵抗はおやめなさい。"
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "ありがとう。このプレゼント、大切にするね。"
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "覚醒体の構造に関してはかなり勉強したから、けっこう専門家だよ。でもシルバーコアの中にある「霊性」っていうのは、ちょっとまだ分からないな……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_139866_UnlockDesc = {
    Text = "霊知啓発レベル11で解放"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "これが、新しい世界の始まり……"
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "わたしには、そういうことが出来るの。ほかの生き物の身体を組み替えたり、調整したり……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_139868_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "どこをどういじればいいのかは、その生き物によってまちまちだから、ちゃんと勉強してからでないと駄目だよ。"
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_139869_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "わたしが怖くないの？あーあ、つまんないの……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "わたしたちの邪魔は誰にもさせないよ"
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "わたしはいつでも大丈夫だよ。"
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "生き物ってほんと、多様性に富んでいるものね。もっとたくさん知りたいな！"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "沙耶と遊んでくれるの？"
  },
  Voice_139875_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_139876_AwakerVoiceContent = {
    Text = "あぅ……"
  },
  Voice_139876_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "これが、新しい世界の始まり……"
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "おなかいっぱい、ごちそうさま！"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "ねぇ、守秘者、あなたはこれまで誰かを愛したことがある？誰かを心から恋しく思ったことってあるの？"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_139880_UnlockDesc = {
    Text = "同調率レベル8達成で解放"
  },
  Voice_139881_AwakerVoiceContent = {
    Text = "ひいっ！"
  },
  Voice_139881_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "このへんかな？"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "お疲れ様！いい収穫はあった？"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "いろいろ検証してみたら、だいぶ分かったよ。それぞれの覚醒体の持つ「霊性」って、まったく異なるもの。で、わたしのシルバーコアの霊性は「愛」みたいだね。"
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_139884_UnlockDesc = {
    Text = "霊知啓発レベル15で解放"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "どう？びっくりした？"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "これがわたしからあなたへの最後のプレゼント。"
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "「このどれかの星に、僕の花が咲いている……」だって。\nあなたも似たようなことを言っていた気がするね。"
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_139887_UnlockDesc = {
    Text = "同調率レベル4達成で解放"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "「シルバーコア」って、どうやらすごく遠くの意志とつながっているみたい。不思議だね……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_139888_UnlockDesc = {
    Text = "霊知啓発レベル7で解放"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "これがわたしからあなたへの最後のプレゼント。"
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_139891_AwakerVoiceContent = {Text = "いや！"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "星の王子さまは、バラが特別に美しく育ったのは、自分が大切に世話をしたからだって言ってるけど……あなたもそう思う？"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_139892_UnlockDesc = {
    Text = "同調率レベル6達成で解放"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "昨日、リリーの本棚に『星の王子さま』っていう本があるのを見つけたの。すっごく面白かった。読んでみたい？"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_139893_UnlockDesc = {
    Text = "同調率レベル2達成で解放"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "うん、シルバーコアの構造を研究もしたし、覚醒体について大まかな形が見えてきたよ。"
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_139895_UnlockDesc = {
    Text = "霊知啓発レベル3で解放"
  },
  Voice_139896_AwakerVoiceContent = {Text = "や！"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_139897_AwakerVoiceContent = {
    Text = "よいしょ！"
  },
  Voice_139897_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "よろしくね！"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "こんにちは！……でいいのかな？\nわたしは沙耶。えぇと、よろしくねー。"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "覚醒"},
  Voice_139901_AwakerVoiceContent = {
    Text = "タンポポって花があるよね。種を風に乗せて飛ばすやつ。綿毛の種は風に運ばれて、故郷から遠く遠く離れて、もしかしたら草木なんか一本も生えてない砂漠に落ちちゃうかもしれない。そんなとき、たった一粒のその種は何を思うのかな……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_139901_UnlockDesc = {
    Text = "同調率レベル10達成で解放"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "何度やっても面白い！"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_139903_AwakerVoiceContent = {
    Text = "えいっと"
  },
  Voice_139903_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "あぶないっ"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "美味しい食事は大好きだよ！わたしに優しくしてくれる人も好き。優しくされると、とてもうれしいなー。"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "あの子がわたしを覚醒させたんだ？なんだかとっても眩しいね……ふぅん、で、あなたはお姉さんを探し出すのを手伝ってあげたの？"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "雑談・ティンクトについて"
  },
  Voice_140534_UnlockDesc = {
    Text = "覚醒体「ティンクト」獲得で解放"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "守秘者の近くにいると、いつも変な人たちが寄ってくるよね。密境にいる時の方がいいかもー。"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "なるほど。了解！"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "守秘者、リンク、覚醒体。あなたが教えてくれた関係でしょ。二人の魂がリンクするのは感じるけど……銀色の糸？とか、うーん、なんか色々と難解だね……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "血肉で種を運ぶ？ふぅん、そうなんだ。あの子のヒツジ、ちょっと興味あるかも。"
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "雑談・タイスについて"
  },
  Voice_140538_UnlockDesc = {
    Text = "覚醒体「タイス」獲得で解放"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "ある種の脅威は、この世界の存続を脅かすほどの闇をもたらす可能性がある、でしょ？知ってるよ。ドール教授から色々と聞いたしね。"
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "雑談・危機について"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "乱暴な人は嫌いだな。嫌な感じがする……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "へぇ、あの子の種族は、他の種族を略奪することによって、新しい惑星で繁殖のチャンスを得ているのね。ふぅん、そうなんだ……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "雑談・ウインクルについて"
  },
  Voice_140541_UnlockDesc = {
    Text = "覚醒体「ウインクル」獲得で解放"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "いい子ね。"
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "特殊スキル・二"
  },
  Voice_141964_AwakerVoiceContent = {
    Text = "えいっ！"
  },
  Voice_141964_AwakerVoiceTitle = {
    Text = "特殊スキル・三"
  },
  Voice_141965_AwakerVoiceContent = {
    Text = "うぅ……"
  },
  Voice_141965_AwakerVoiceTitle = {
    Text = "被ダメージ・五"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "残念だね、気が変わったときは、どこで私を見つければいいかわかっているだろう。"
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_143501_UnlockDesc = {
    Text = "霊知啓発レベル15で解放"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "くそっ…………"
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "皮膚、筋肉、神経、骨格、それらはすべて再構築され、再び健康で完全な状態となり、再び活力を取り戻す。"
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_143503_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "海の前に、破壊できない敵など存在しない！"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "宴会、狩り、庇護？\nあなたが祈るなら、最も古い海水があなたに私の名を告げるだろう。\n我こそは深淵の主、ポントス。"
  },
  Voice_143505_AwakerVoiceTitle = {Text = "覚醒"},
  Voice_143506_AwakerVoiceContent = {
    Text = "ふふ、エポヤンスでの時を懐かしんでいるのかい…………\nそれはこの身体の中にある、いつでもあなたの帰りを歓迎しているよ。"
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "私はそうしなかったけれど、もしいつかあなたの耳の中に海水と翼のはためく音が聞こえても、心配しないで。正常なことだから。"
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "あなたの感覚を捧げよ、永遠に深淵の中で反省し続けるがいい！"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "私は活気ある若者が好きだが、残念なことに、ミサゴは狂宴への管制が厳しすぎて、まともな狩り場すら一つもない。\nしかも、その中には、堂々と表を歩き回り、教授などという肩書きまで掲げているあの汚らわしいものがいる。"
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "雑談·ミサゴ大学について"
  },
  Voice_143510_AwakerVoiceContent = {Text = "ふっ！"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "被撃·一"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "これだけのことをしてやったのに、もう一度おじさんと呼んでさえくれないとは、まったく頭が痛いね。"
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "雑談·守秘者について"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "焦ることはない、海の最深部のダークが必ずあなたたちを捕食するだろう。"
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "跪け、エポヤンスの糧となれ。"
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "特殊スキル・三"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "私を選んだその存在については…………友好的でもあり、悪辣でもあると言うほかない。\nどこに落とすかは全くの気まぐれで、必ず危険から救い出してくれるが、その場所がまた別の危険かどうかは、今回の「旅程」が考えることではない。\nなんと面白い、なんと予測しがたいことか、私はこの伝統を受け継ごうかと考えている。"
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_143515_UnlockDesc = {
    Text = "同調率レベル8達成で解放"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "私とエポヤンスの間には特別な繋がりがある。むしろ、私こそがエポヤンスであり、エポヤンスは私によって維持され、私の身体を通じて存在している。"
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "雑談：エポヤンスについて"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "頭を上げ、その喉を晒せ。"
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "記録を消し、存在を抹消する。どこか馴染み深い…………私の言いたいことはわかるだろう、源は違えど、祂らは常に光なき場所から生まれ出るようだ。"
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "雑談·危機について"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "貴様らは愚かにも私の威厳を侵すべきではなかった。"
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_143520_AwakerVoiceContent = {Text = "弱い！"},
  Voice_143520_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "エポヤンスでは、狂宴は決して止まらない。そしてエポヤンスの敵もまた、永遠に安らぎを得ることはない。"
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_143521_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "ああ、あなたの戦慄は私にも伝わってくるが、それは全く不要なことだよ、若い友よ。\n平凡さと消耗されることへの恐怖を受け入れて、私を見なさい——あなたには常に別の選択肢があると、わかるはずだ。"
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_143522_UnlockDesc = {
    Text = "霊知啓発レベル7で解放"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "そうだ、あの災厄が彼の直接の指示ではなく、遊びの途中の偶然に過ぎないことはわかっている。だがそれは明らかに、私が彼を殺したいという気持ちをさらに強めるだけだ。\nあの黒い霧は一人でいないようにするべきだし、私に捕まらないようにすることだ。"
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "雑談·嫌いなもの"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "あのぬめぬめした魚人たちは私の友ではなく、敵だ。意外かい？海はもともと彼らのものではないのだから。"
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_143524_UnlockDesc = {
    Text = "同調率レベル2達成で解放"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "永遠に、ここに留まれ！"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "知恵の覚醒"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "準備はいいか、獲物たちよ！"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "霊性が新たな躯体を生み出し、躯体には取るに足らない知識が詰め込まれ、そしてあの美しく生き生きとした個体たちは永遠に一か所に集い続ける。\n私が言ったことを覚えているか、海の最深部はすべてを受け入れ…………すべてを留め置く。"
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_143527_UnlockDesc = {
    Text = "霊知啓発レベル3で解放"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "魇よ、祂らを食い止めろ。"
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "この小さな子たちがあなたを食い尽くさなければいいけどね。わかるでしょう、大家族を養うのは確かに簡単なことじゃない。"
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "遥か遠い昔、陸地がまだ海に浮かび上がる前、この星はある特別な霊性を目覚めさせた。強大で、威厳があり、覗き見ることのできない存在を。\n祂らは敵意とも友好とも定義できず、人類はかつての無数の生き物と同様、祂らにとって取るに足らない存在であり、塵のように払われることもあれば、領土とともに守られることもある。"
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_143530_UnlockDesc = {
    Text = "同調率レベル4達成で解放"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "老いだけが、あなたが独りで向き合わなければならない冒険、最良の友にして最も手強い敵だ。エポヤンスの灯りがそれを追い払ってくれる…………ただ些細な記憶に過ぎない、それらに縛られる必要はない。"
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_143531_UnlockDesc = {
    Text = "霊知啓発レベル11で解放"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "逃げるという幻想は捨てるがいい。"
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "あなたは灰白の粉末と化すだろう。"
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_143534_AwakerVoiceContent = {Text = "ふん！"},
  Voice_143534_AwakerVoiceTitle = {Text = "攻撃"},
  Voice_143535_AwakerVoiceContent = {
    Text = "賢い判断だね、坊や。外来のモンスターの信者はいつも愚かで、死体を海に投げ込む。それは贈り物とは言えないだろう？"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "あなたはもう目をつけられた。"
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "特殊スキル・二"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "認めたくはないが、ごくごく稀に、老いとは時間がもたらす唯一のものではなく、ただの象徴に過ぎないと感じることがある。\nだから、私はそれが私の上に存在することを許している。もちろん――外見だけに限った話だが。"
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "雑談·好きなもの"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "祈りは有効だよ、想像してみなさい——虫があなたの前でレオ文字を並べたとしても、あなたはその虫の訴えに応じることを少しは考えるだろう。"
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_143539_UnlockDesc = {
    Text = "同調率レベル6達成で解放"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "はははは、さあ、そのかおもじはやめなさい、坊や。\nそれはただ、いわゆる「旧き神々」が従うべき伝統に過ぎない。あなたに関しては、いかなる代償も条件も必要ない、私は永遠にあなたの味方だ。"
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_143540_UnlockDesc = {
    Text = "同調率レベル10達成で解放"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "ふん、外来のモンスターと結託した小モンスターめ。\nよりにもよって、私と彼を同じ神壇に並べる愚か者がいるとは、まったく侮辱もいいところだ！"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "雑談：トゥルーについて"
  },
  Voice_143554_UnlockDesc = {
    Text = "覚醒体「トゥルー」獲得で解放"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "敵の敵は友、機会があれば、宿敵が最も気に入っているおもちゃを奪い取るという良い取引をするのも吝かではない。"
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "雑談：ライカーについて"
  },
  Voice_143555_UnlockDesc = {
    Text = "覚醒体「ライカー」獲得で解放"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "ほお？我と戦うというのか？我は構わん。"
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "もっと！もっと力を寄越せ！"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "意志を貫けん奴は嫌いだ。そういうのは往々にして弱さの表れだからな。だが、お前は例外だ。これまで我は、多くの物を背負った者は、遠くまで進むことはできんと考えていた。しかし、お前の歩く道は、我ですら驚かずにはいられん……もしかすると、自分とは違う道を歩む者だからこそ、育て上げ、挑むに値するのかもしれんな。そうだろう、「好敵手」よ！"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "雑談·守秘者について"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "星天を泳ぐ鯨よ、すべてを吞み込め！"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "我と戦えることを光栄に思え！"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "星の海よ、破滅を見届けるがいい！"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "足りん。まだまだだ……"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_146165_AwakerVoiceContent = {Text = "フッ！"},
  Voice_146165_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_146166_AwakerVoiceContent = {Text = "フン！"},
  Voice_146166_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "この世界が消えようと、我の知ったことではない。だが我が力を追い求める道を邪魔することは許さん。"
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "雑談·危機について"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "定められた滅亡の到来を前に、あらゆる存在の意義を疑い始めるとは……そのように子どもじみたつまらん論争に付き合う気はない。滅亡など気に留めるな。記憶に残す必要もない。力こそがこの世の意義であろうが。"
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "雑談：溶融・ドールについて"
  },
  Voice_146168_UnlockDesc = {
    Text = "覚醒体「溶壊・ドール」獲得で解放"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "お前の目に、この世界のものではない意志を見た。純粋ではないが、強靭な意志だ。さあ！証明してみせろ！お前はどんな力と欲望によって、我の前に立っているのだ！"
  },
  Voice_146169_AwakerVoiceTitle = {Text = "覚醒"},
  Voice_146170_AwakerVoiceContent = {Text = "ハッ！"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "我と戦えることを光栄に思え！"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "混沌の息吹よ、久しいな……虚無の中から生まれたその瞬間から、我が追い求めるものは何も変わらぬ。"
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_146172_UnlockDesc = {
    Text = "霊知啓発レベル3で解放"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "我に挑むか？その勇気を讃えて、我に打ちのめされる栄光をくれてやろう。「ミサゴの守秘者」への礼儀としてな。"
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_146173_UnlockDesc = {
    Text = "同調率レベル4達成で解放"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "弱者、臆病者、夢見るバカどもが溢れ返っている偽物の理想郷だ。だが、そんなことはどうでもいい。我はここで最高に滾らせてくれる敵に出会うことができた。それだけで十分だ。"
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "雑談·ミサゴ大学について"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "強大な力を持っていながら、恐怖に罪悪感、疲労に屈し、自らの才を果てのない夢の中に閉じ込めるとは。実にもったいない。"
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "雑談：トゥルーについて"
  },
  Voice_146175_UnlockDesc = {
    Text = "覚醒体「トゥルー」獲得で解放"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "あっけないものだ。"
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "封印が少し緩んだか……星の海の力が底から湧きあがってくる。久しぶりの感覚だ……"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_146177_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "星天を泳ぐ鯨よ、すべてを吞み込め！"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "……痛快だ。"
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "被撃·一"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "我は長きにわたり星の海を漂いながら、己の強さを勘違いした連中をこの手で深淵に送り込んできた。お前には特別な何かがある。だが我と共に歩きたいのなら、まずは堂々と前を見ろ。臆病な同行者など、我にはいらぬ。"
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_146180_UnlockDesc = {
    Text = "同調率レベル6達成で解放"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "勇敢な者、臆病な者、強き者、弱き者……フッ！いや、相手がどんな人間かなど、どうでもいい。実力さえあれば、我は最高の気分になれる。"
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "雑談·好きなもの"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "弱さ。この世界には吐き気がするものが無数にあるが、中でも罪深いのが弱さだ。誰もが剣を持ってこの世界に生まれ落ちる。手を抜くこと、敗北を思い描きながら避けられぬ戦場に立つなど絶対に許されん。それは相手への、そして己自身への侮辱に他ならぬ。"
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "雑談·嫌いなもの"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "朽ち果てし星の骸よ、目覚めよ——"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "知恵の覚醒"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "フッ……心躍るいい相手だった。次はもう、手加減せんぞ。"
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "喜びのあまり骨が震えておるわ……お前の努力は、確かにこの目で見た。これはお前が我の隣に立つ資格があるという証明となるであろう、守秘者よ。"
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_146185_UnlockDesc = {
    Text = "霊知啓発レベル7で解放"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "フッ……よく分かっただろう、守秘者よ。力の枷とは打ち砕かれるためにあるのだ！"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_146186_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_146187_AwakerVoiceContent = {Text = "ほう？"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_146188_AwakerVoiceContent = {Text = "ほう？"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "あと少しで……我が生涯追い求めてきた、あの力の終結が…….我と共に歩み、我をここに導いたのはお前だ。お前と一緒にその究極の日を見届けるのを楽しみにしているぞ！"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_146189_UnlockDesc = {
    Text = "霊知啓発レベル11で解放"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "どうやら我はお前を見くびっていたようだ……その成長速度、そしてその潜在能力は、我の予想を超えている。これまで時の流れと共に消え去る命を数多く見てきた。だがお前は……何かが違う。教えろ。お前のその力は、いったいどこから来ているのだ？"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_146190_UnlockDesc = {
    Text = "同調率レベル8達成で解放"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "地獄の口よ、我がために開け！"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "ああ、そうか……力の終結は存在しなかったのか……本当の挑戦が、今我のために扉を開いている！お前がここに連れてきてくれたおかげで、すべて理解した。すぐにお前の目の前に、より一層完璧になった戦士を連れてきてやる。そのときには、より一層完璧なお前も見たいものだ、我が「好敵手」よ。"
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_146193_UnlockDesc = {
    Text = "霊知啓発レベル15で解放"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "小賢しい。"
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "力が骨の中で沸きあがっている！"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "すべてを呑み込む！"
  },
  Voice_146196_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_146197_AwakerVoiceContent = {
    Text = "憐み、弱さ、迷い……お前の目は雑念にあふれている。一つの意志を貫けぬ者に、力とは何かを理解することはできぬ。"
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_146197_UnlockDesc = {
    Text = "同調率レベル2達成で解放"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "真の力とは、復讐やガーディアンとは無縁のものだ。力はただ力であり、もう一人の私はこの道理を「真に」理解したことがなかった。それこそが、彼女が十分に強くなれなかった根源だ。"
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "雑談：ロータンについて"
  },
  Voice_146198_UnlockDesc = {
    Text = "覚醒体「ロータン」獲得で解放"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "一度しか言わぬ、よく聞け。\nこのロータン、お前を待つに値する好敵手として認めることにした。\nお前が頂点に辿り着くまでは、我がお前の信頼できる剣となってやる。この誓いは、忠誠心や感情とは無関係だ。最高の好敵手に途中で死なれては困る。ただそれだけだ。"
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_146199_UnlockDesc = {
    Text = "同調率レベル10達成で解放"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "さあ、我を殺してみろ。さもないと殺されるぞ。"
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "地獄の口よ、我がために開け！"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "骨の刃の一振りで、万物よ砕け散れ！"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "力に……果てなどない！"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "特殊スキル・二"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_147493_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "（かすれた穏やかな歌声）"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "観客を……もっと観客をください……"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "砂……白い砂漠……ここは危険だ、一緒に離れよう。"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_147496_UnlockDesc = {
    Text = "同調率レベル4達成で解放"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "新しい故郷の地図は、今でもちゃんと覚えています。景色が色鮮やかでとても美しい星でした。あの星こそ、私たちの帰るべき場所です。あそこでなら私は心のままに歌い……幸せになれるのです。"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "雑談·好きなもの"
  },
  Voice_147498_AwakerVoiceContent = {
    Text = "あ……っ。"
  },
  Voice_147498_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_147499_UnlockDesc = {
    Text = "同調率レベル10達成で解放"
  },
  Voice_147500_AwakerVoiceContent = {
    Text = "え…………？"
  },
  Voice_147500_AwakerVoiceTitle = {
    Text = "被撃·一"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "これは……星の声。"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "またいらしたのですね。昔のように私の隣に座って、一緒に待ちましょう。……何を待っている、か？……待っている、ええ……待っているのです。"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "雑談·守秘者について"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "完璧なリハーサルが出来ました。もう準備は万端です。"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_147503_UnlockDesc = {
    Text = "霊知啓発レベル11で解放"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "落ちて。"
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "破滅よ、死よ！"
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "知恵の覚醒"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "私は狂ってなどおりませんし、悲しみを感じてもいません。根も葉もない噂を信じないでください。"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "雑談·嫌いなもの"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "おかしいですね。あの方たちは私の歌声に怯えていたようです。"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_147508_AwakerVoiceContent = {
    Text = "眠りなさい。"
  },
  Voice_147508_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "素敵な舞台衣装ですね。キラキラしていて……"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_147509_UnlockDesc = {
    Text = "霊知啓発レベル7で解放"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "空に残された、哀れな星の光よ！"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_147512_AwakerVoiceContent = {
    Text = "歌います。"
  },
  Voice_147512_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_147513_AwakerVoiceContent = {
    Text = "正しい発声練習……？でも、私は今の声に満足しています。"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_147513_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "なんだか……声に変化が……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_147515_UnlockDesc = {
    Text = "霊知啓発レベル3で解放"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "——……、いかがでしょうか。歌声はお気に召しましたか？"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "覚醒"},
  Voice_147517_AwakerVoiceContent = {
    Text = "おやすみ"
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_147519_AwakerVoiceContent = {Text = "はい。"},
  Voice_147519_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_147520_AwakerVoiceContent = {
    Text = "あ……っ。"
  },
  Voice_147520_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "ありがとうございます……と、言うべきなのですよね。"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_147522_AwakerVoiceContent = {Text = "はぁ。"},
  Voice_147522_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_147523_AwakerVoiceContent = {Text = "輝け。"},
  Voice_147523_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "——…………、こんな風に歌うのは久しぶりです。ようやく舞台に戻れました。……ありがとうございます、守秘者様。"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_147524_UnlockDesc = {
    Text = "霊知啓発レベル15で解放"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "すみません……私を木から下ろしていただけないでしょうか？その……なぜ登ったのかは覚えていなくて……空に漂う雲が、懐かしくなったのかもしれません。"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "私の一族はいなくなったわけではありません。ただ遠い……遠いところに行っただけです。"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "雑談・同族について"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "聞こえますか？"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_147528_AwakerVoiceContent = {Text = "おお。"},
  Voice_147528_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "いつも私の周りをうろついているようだ……わかった、君は私のファンだね。"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_147529_UnlockDesc = {
    Text = "同調率レベル6達成で解放"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "ラララ～……ここにも世界を滅ぼす災厄があるのですか？……えっと、では髪を整えたら、姉さんのところへ向かいますね。"
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "しっ……お静かに。悪者がきました。私と姉さまを捕まえて船に乗るのを邪魔する悪者です。"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "雑談・安全について"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_147532_UnlockDesc = {
    Text = "同調率レベル2達成で解放"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "目覚めたとき、惑星は破壊されていました。夜空が一筋一筋と剥がれ落ち、世界は強風に吹かれたキャンバスのように変形し、その後裂け、粉々になりました。"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_147533_UnlockDesc = {
    Text = "同調率レベル8達成で解放"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "これはピックマンさんが描いてくださった、私のサイン入りのポスターです。あなた様に差し上げますね。"
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "雑談・ファイントについて"
  },
  Voice_147534_UnlockDesc = {
    Text = "覚醒体「ファイント」獲得で解放"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "ん？気になる？教母の宝庫は、むやみに外の人に見せるわけにはいかないわよ。中にぎっしり詰まっているものを知りたければ、今すぐフェアリー教派に入ってみたら、ふふ？"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "カラブの結論が信じられない？うぅ、やっぱり誤魔化すのは難しいわね……実は私は@1公国のボエモン六世の庶子で、名を隠して人間界に流れ着いたの、敵軍の追跡から逃れるために仙女と偽っていたのよ……一番大切な秘密まで話したのに、信じてくれないの？"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_149668_UnlockDesc = {
    Text = "同調率レベル6達成で解放"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "いたたた〜"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "被撃·一"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "飴を食べすぎ？いいえいいえ、これが教母の笑顔を保つ秘訣なのよ、虫歯ごときで止めるわけにはいかないでしょ？〜〜"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "雑談·好きなもの"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "さあ、この仙女の傍においでなさい。何ですって？みんなで一緒に供物を分け合って食べる？……まあ、それがミサゴの決まりなら……私は……もちろん何も反対意見なんてないわよ、さあ、みんなで賑やかにしましょう！"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_149671_UnlockDesc = {
    Text = "霊知啓発レベル15で解放"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "あらあら、なんて敬虔な子羊ちゃんなの。"
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "もう少しだけ、妖精が祝福してあげるわよ？"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "あなたたちはまだまだね〜"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "今回の礼拝の儀式は、いつもよりずっと盛大で、捧げ物の数も多くなければなりません……あら、もちろん人柱なんかじゃないわよ、私は心優しい仙女ですもの、人を傷つけるようなことはしないわ〜"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_149676_UnlockDesc = {
    Text = "霊知啓発レベル3で解放"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "シークレットキーパー、カラブの本音を聞く準備はできていますか？\nカラブがどこから来たかなんて、全然重要じゃないわ。大切なのは、あなたが天が私に与えてくれた最も尊い贈り物だということ、カラブは永遠に、永遠にあなたという貴人の傍にいると決めたのよ。\nこれも追跡をやめさせるための策略の一部だと思う？ふふ、どう思う？\nとにかく、本音を話したご褒美に、リンゴ味のグミをひとつくれる？"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_149677_UnlockDesc = {
    Text = "同調率レベル10達成で解放"
  },
  Voice_149678_AwakerVoiceContent = {Text = "ふふ〜"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "大丈夫よ、次は妖精を守ることに集中すれば、失敗しないわ〜"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "騙そうとしても無駄よ！"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "うわあ、こんなにたくさんの貢ぎ物が……こほん、ふふん、よくやったわ、褒めてあげる！さあ、仙女が仙女のキスをプレゼントしてあげる！何を考えてるの、もちろんおでこにするのよ！"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_149683_UnlockDesc = {
    Text = "霊知啓発レベル7で解放"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "信者の皆様のご奉納に感謝いたします！心優しい教母が神殿にあなたの純金像を建立してさしあげましょう。あらまあ、その像があなたの凛々しく美しい姿を表現できるよう、もう少し集め直さなければなりませんわね〜"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_149684_UnlockDesc = {
    Text = "霊知啓発レベル11で解放"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "あなた？……あなたは私たちの教会のまだ悟りを開いていない一員よ、カラブは忍耐強く、あなたが世界の真理に気づく日を待ちましょう。その時には、教主に肉体と忠誠と財産を捧げることを忘れずにね、ふふ。"
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "雑談·守秘者について"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "リストのものが……もう全部揃ったの？ミサゴの財力は底知れないわね……知っていたら私は……んん？何をぶつぶつ言ってるの？ただロード・デクスターの気前の良さに感謝していただけよ、ふふ〜"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_149686_UnlockDesc = {
    Text = "霊知啓発レベル2で解放"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "一番嫌いなもの？もちろん契約を守らない魔法使いたちよ。こっそり教えてあげるけど、実はすべての魔法使いは大嘘つきで、彼らが言う予言や呪いはみんなあなたを一文無しにするためのものなの！対策は……あなたのお金に仙女の祝福を受けさせればいいだけよ！"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "雑談·嫌いなもの"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "はじめまして、遠方からやってきた蒼白の妖精よ。興味があったら聞いてみる？妖精の祝福は会費のランクによって強さが違うのよ、ふふ〜"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "覚醒"},
  Voice_149689_AwakerVoiceContent = {
    Text = "これまでの礼拝の儀式では、七度の礼拝と三度の宣誓の流れのほかに、信者たちが私のために新しい神殿を特別に建て、豊かな供物を捧げてくれていたわ。これがリストよ！"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_149689_UnlockDesc = {
    Text = "霊知啓発レベル1で解放"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "さあ、手放したいものを全部深い雪の中に埋めてしまいましょう……"
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "私の出自を調べているそうね、ふふ、それは教母の秘密よ。でも、どうしても調べたいなら、フェアリー教派に私が自ら書いた伝記が保管されているわ。シルバーコア十万枚を納めれば閲覧できるの、試してみる？"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_149691_UnlockDesc = {
    Text = "同調率レベル2達成で解放"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "いいわね、ここにはとても可愛い子供たちと、呆れるほど気前のいい生活補助があるわ。彼らのおかげで、いずれ東方へ向かう旅費を貯められそう……"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "雑談·ミサゴ大学について"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "教母への礼拝を忘れずにね、ふふ。"
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "知恵の覚醒"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "ごめんなさいね、仙女の領地はとても神聖なの、変な狼人はお断りよ……空気に嘘の匂いがするとか何とか、鼻がおかしくなっただけじゃないの？"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "雑談：ライカーについて"
  },
  Voice_149694_UnlockDesc = {
    Text = "覚醒体「ライカー」獲得で解放"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "あら、偽物の仙女だって言う人がいるのね……バレちゃったわ、ふふ。あなたは気にしないわよね？"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "雑談·噂について"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "んむ、おいし〜"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "安心して〜"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "道を踏み外した子羊たちよ、この妖精がその罪を洗い清めてあげるわ、ふふ〜"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "まだ諦めないの？じゃあ、カラブが直接教えてあげましょう。実はカラブは東方の雲を突く高い雪山の女神ウモパティの娘なの……ん、その女神には息子が二人いるだけで娘はいないって？神明に関する記録にはいつも欠けている部分があるものよ。"
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_149699_UnlockDesc = {
    Text = "同調率レベル4達成で解放"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "じゃじゃーん〜妖精の光輝があなたに降り注いだわ、さあ行って！"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "もういいから調べるのをやめてよ、ね？この失礼な行為をおとなしく止めてくれたお礼に、一番大切な飴を半分こっそり分けてあげる。東征軍の戦場では、甘い飴なんて貴重なものなのよ。"
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_149701_UnlockDesc = {
    Text = "同調率レベル8達成で解放"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "カラブの祝福は世の中のあらゆる病を癒せるわ、もちろんこの黒い疫病も癒せる……もちろん本当よ、あなたが十分に敬虔で、十分にカラブを信頼すればいいだけよ、ふふ。"
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "雑談·危機について"
  },
  Voice_149703_AwakerVoiceContent = {Text = "嫌い！"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "妖精の光輝〜"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "七度の礼拝、三度の宣誓、それらを捧げて妖精の赦しを得なさい！"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "感じろ！"
  },
  Voice_150079_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_150104_AwakerVoiceContent = {
    Text = "あら、オジールはどうしてあなたを通したの？全員を止めるって約束したじゃない？あなたは彼の主君……？頼りにならない子ね、本当に困るわ、この集会のために私がどれだけ準備に力を注いだか。いっそ……受け取った供物を五分五分で分けるから、今回は見逃してくれない？"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "雑談：オジールについて"
  },
  Voice_150104_UnlockDesc = {
    Text = "覚醒体「オジール」獲得で解放"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "さっさと終わらせてかーえろ。"
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "彼はわたくしが眠っている間に教団に入ったから、ほとんど面識がないのよね。\n人間の姿を捨てて完全な「海踊人」になりたいって、自分から訪ねてきたんですって……ふん、力に固執するなんて愚かだわ。"
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "雑談・カエクスについて"
  },
  Voice_36679_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "ゴリアテは忠実な犬じゃないわよ。鎖につながれてなければ、真っ先に逃げたに決まってるわ。……どうしてミリアムは彼を大事にするのかしら？わけがわからないわ。"
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "雑談・ゴリアテについて"
  },
  Voice_36680_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "海踊人はあの姿で生まれるわけじゃないわ。人にまぎれる為に、人間と変わらない姿で半生を過ごすの。\nだから気をつけなさい。お前の大好きなケーキ屋だって、海踊人の一員かもしれないわよ？"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "雑談・海踊人について"
  },
  Voice_36681_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "シレストの調子の狂った船歌、船長が作ったベーコンと魚の煮込み、硬くて海風で生臭くなった布団……危ないことも多くて緊張したけど、海に亡命したあの数か月を……彼らと過ごした日々を、一生忘れないわ。"
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "雑談・「幽霊船」について"
  },
  Voice_36682_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "大学のみんなは忙しそうにしてるけど、ここには今まで感じたことのない安らぎがあるわ。同じ目標に向かって、一緒に努力してる感じ……まあ、悪くないわね。"
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について・Ⅱ"
  },
  Voice_36683_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "ベッドは硬すぎるし、部屋は寒すぎるし、紅茶は草みたいな味がするし……ここが嫌いな理由は山ほどあるわ。\nでも、「お前がいる」から、悪くない……じゃなくて、我慢してあげなくもないわ！"
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "雑談・守秘者について・Ⅲ"
  },
  Voice_36684_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "あ、ありがとう……え？なんのお礼かって、そんなの決まってるでしょ！？お前には、海で助けてもらったから……ちょ、なんで笑ってるの？まさか、わたくしをからかうつもり！？"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "雑談・守秘者について・Ⅱ"
  },
  Voice_36685_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "わたくしと彼女の間には、家族の愛があるのだと思っていたの……でもいろいろあって、そんなの思い込みに過ぎなかったんだって、やっと気づいたわ。\n彼女をどうするかは、お前たちの問題よ。\nこれ以上わたくしに近づけないでちょうだい。"
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "雑談・ミリアムについて・Ⅱ"
  },
  Voice_36686_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "こんなの変よ……本当におかしいわ。\n心臓はもう動いてないのに、体はまだ暖かいの……ねえ、わたくしの手を握ってみて。気のせいじゃないって確かめて。"
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "雑談・「覚醒体」について"
  },
  Voice_36687_UnlockDesc = {
    Text = "「調査」第6章クリアで解放"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "私はレオ王国の生まれではありません。しかし大聖堂は、私が生まれ変わった場所なのです。それゆえ、私はここを故郷だと感じています。"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "雑談・故郷について"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "未知なる疫病が蔓延り、何年も経った頃……ようやく神に私の祈りが届き、苦しみに対抗する「恵み」を与えてくださいました。その「恵み」は確かに患者に生命力を与えますが、代償を伴うものでした。\nゆえに、神の代行者である私は、「恵み」を受けいれた人々に代わり、代償を負うたのです。"
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "雑談・「祝福」について"
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "覚醒体として生まれ変われたことは、神からの賜った恩寵なのです。過去の無念を晴らす機会を与えられたのだと、そう信じています。私は必ず、代行者としての役目を全うし、この世から苦しみを取り除いてみせましょう。"
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "雑談・「覚醒体」について"
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "あなたは私の望みに応え、審査会に対し、秘密を守ってくださった。……審査会が介入すれば、私が聖堂区に仕えることなど決して許されなかったでしょう。改めて感謝を申し上げます、白き炎よ。"
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "雑談・守秘者について・Ⅱ"
  },
  Voice_45156_UnlockDesc = {
    Text = "特務記録「血の色」クリアで解放"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "彼は素直で、しっかりとしていて、心優しい、かけがえのない明るい魂を持っています。彼のような人に出会うのは、前の人生以来ですね。"
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "雑談・オジールについて"
  },
  Voice_45157_UnlockDesc = {
    Text = "特務記録「血の色」クリアで解放"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "視覚を失いはしましたが、盲目となったわけではありません。神は私の世界を闇に包むと同時に、魂のかすかな光を見る力を与えて下さいました。"
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "雑談・視覚について"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "あの頃の私は、「恵み」を与えられただけの、ただの人間でした。すべての人を救いたいと願っても、「恵み」を必要とする人は多く、この手を届けることが出来ませんでした。それこそが私の最大の心残りであり、永遠に消えぬ罪なのです。"
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "雑談・一度目の生について"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "教皇庁の者たちは、《聖典》に出てくる『白き炎』とは月の光のことであり、月の光から白き御使いが現れ、私たちを苦難から救うと考えています。ですが、私は知っているのです。本当の炎とは、私たちの燃える魂のことだと。"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "雑談・「白き炎」について"
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "私の正体を隠したのは大司教様の意向でした。理由は何も語らず、「明るいところにも陰はある、善行を成すときも油断をしてはならない」とだけ、私に警告したのです。\nご心配なく、あなたにはもちろん、全幅の信頼を寄せていますよ。"
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "雑談・正体を隠すことについて"
  },
  Voice_45161_UnlockDesc = {
    Text = "特務記録「血の色」クリアで解放"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "私の歌声は、お力になれましたか？"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "くぅ……同じ子どもなのに、どうしてみんな彼のことは尊敬してるって言うの？わたくしのことも同じように敬いなさいよね！"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "雑談・トゥルーについて"
  },
  Voice_4909_UnlockDesc = {
    Text = "覚醒体「トゥルー」獲得で解放"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "ねぇ、他の覚醒体は普段なにしてるのか知ってる？ちょ、勘違いしないで、友達を作りたいとか、そういうのじゃないから！わたくしはただ……そう！観察したかっただけなの！"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "雑談・日常について"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "くそくそくそ！奴らをずたずたに切り刻んで、蜘蛛の餌にしてやる！"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_4912_AwakerVoiceContent = {
    Text = "余韻が……"
  },
  Voice_4912_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_4913_AwakerVoiceContent = {
    Text = "韻律が……"
  },
  Voice_4913_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "大胆じゃな。"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "何か焦っているのですか？私に手伝えることはあるでしょうか？"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "よくもッ！"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_4917_AwakerVoiceContent = {Text = "ほう？"},
  Voice_4917_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "もっとも尊いものは、わたくしに至高の地位を授けた赤ん坊よ。わたくしらしくないって……そう、かしら？"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_4919_AwakerVoiceContent = {Text = "何か？"},
  Voice_4919_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "へへ、よくできたっしょ！そんじゃ報酬ちょーだい。言っとくけど、ただでお前を助ける義理なんてあたしにはないからな？"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_4921_AwakerVoiceContent = {
    Text = "どっか行け！"
  },
  Voice_4921_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "危ないっ！"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "美しい勝利だったわ……この瞬間を永遠に残したいくらい。"
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "穢れの源を感じる……本体にまた一歩近づいた……ああああ、私が世界を切り裂いてやる！"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_4924_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "準備ができたわ。指示をお願いね、旦那様。"
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_4925_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "旦那様、あなたはとても親切な方ね。でも残念だけど、私はお返しすらまともにできない、ただの出来損ないなの……"
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_4926_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "……あと少しで、「彼女たち」から離れることができるの？"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_4927_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "あれ、まだ生きてるわ……本当に私の臓器を取ったり、実験体にするわけじゃないの？"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_4928_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "ウインクルの一族は、生物の脳内に寄生する力を持っているわ。わたしのウィルもそのことで彼女を恐れている。まあ、今の彼女は、躯に縛られた哀れな魂に過ぎないけど。"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "雑談・ウインクルについて"
  },
  Voice_4929_UnlockDesc = {
    Text = "覚醒体「ウインクル」獲得で解放"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "アイギスは、この世界のすべてが好きなんです。ワークハウスで食前の祈りを捧げる時や、守秘者さんが任務から帰ってくるのを、みんなで待ってるときとか、穏やかで幸せな感じがします……でも、アイギスに、幸せを感じる資格があるでしょうか。"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_4931_AwakerVoiceContent = {Text = "沈め。"},
  Voice_4931_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "咲き誇れ。"
  },
  Voice_4932_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_4933_AwakerVoiceContent = {
    Text = "「信頼」「服従」「奴隷」「恋」「尊敬」……言語モジュールを再構築しています。守秘者様、学習にご協力をお願いします。"
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_4933_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "エリカは現在待機中、本体の冷却が1時間15分後に終了します。——<Del:起動したければ心臓を交換しろ>——緊急起動しますか？……権限認証中……最高権限の認証が完了しました。こんにちは、守秘者様。"
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_4934_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "調査任務の平均危険指数7、平均医療損耗は錬金補充剤8本、死体の後処理にかかる平均時間は10時間です。結論、守秘者の仕事は非常に危険なため、作戦中はくれぐれも気をつけてください。"
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_4935_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "教師プロフィール検索中、エリカ・ライフェル。シルバーコア機械とオートメーション学科の講師で、既に死去——お探しのデータはこちらですか？かしこまりました、別のデータをお探しします。キーワード「エリカ」再検索しています。"
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_4936_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "曖昧検索は現在利用できないため、情報を検索したい場合は、ファイルのフルネームを指定してください。"
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_4937_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_4938_AwakerVoiceContent = {Text = "あ……"},
  Voice_4938_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_4939_AwakerVoiceContent = {Text = "ああ。"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "ああっ……"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_4941_AwakerVoiceContent = {
    Text = "あ……っ。"
  },
  Voice_4941_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "チャージ完了。\n爆破、開始。"
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "チャージ完了。\n爆破、開始。"
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "これしきのことで、王女の休息を邪魔しないでちょうだい。"
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "ティンクトを守ったときと同じように、あなたを守ります。"
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "わたくしは重要な人物ではなく、多くの信者の一人に過ぎません……主に仕え、かの方にお目にかかれるのであれば、魂を捧げても後悔はございません……"
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "雑談・過去について"
  },
  Voice_4946_UnlockDesc = {
    Text = "覚醒体「トゥルー」獲得で解放"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "私を見なさい！"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "私を見なさい！"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "よかろう、あの狂信者どもが余の邪魔をせんのであれば、同じ部屋にいることを許そう。"
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "雑談・海踊人について"
  },
  Voice_4949_UnlockDesc = {
    Text = "覚醒体「ミリアム」「ゴリアテ」「カエクス」「サンガー」「ファロス」いずれか獲得で解放"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "あの暗い感じが嫌いよ。胸にぽっかり穴が空くみたいで、欲求が満たされなくて、全身がむずむずするの……"
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "やめてやめてやめてやめてやめてその話しないで……"
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_4953_AwakerVoiceContent = {
    Text = "神のご慈悲があらんことを。"
  },
  Voice_4953_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_4954_AwakerVoiceContent = {
    Text = "安らかにお眠りなさい。"
  },
  Voice_4954_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "神の国は滅んだと結論づける学者たちは、なんと愚かなのでしょう。ですが、何を言われようとかまいません。神の国を再建する上で、学者の言葉などなんの障害にもなりませんから。"
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "実は……今のバイクにはかなり不満があるんだ。嫌いなわけじゃないけど、何かが足りないような気がしてて……なんだろう？"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_4957_AwakerVoiceContent = {
    Text = "他言無用じゃ。"
  },
  Voice_4957_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_4958_AwakerVoiceContent = {
    Text = "切り刻む！"
  },
  Voice_4958_AwakerVoiceTitle = {
    Text = "スキル・躁狂・二"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "ごめんなさい……"
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "スキル・抑鬱・二"
  },
  Voice_4960_AwakerVoiceContent = {Text = "あら？"},
  Voice_4960_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2年、ワード・フィリップス氏、クラークシュ、タヴィの3人が、ミサゴ大学を設立しました。その後、長い時間を経てようやく——<Del:この忌まわしき監獄> ——ミサゴ大学となりました。"
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "正義感、忠誠心、くじけない強さ、自律。これらは俺の心に、しっかりと刻み込まれている。"
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "私はあなた様に従います。"
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "妖魔の盾の名前を、娘につける親がいるなんてね。え？あの子には両親がいないの？そう……じゃ、彼女には知られないようにしないとね。"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "雑談・アイギスについて"
  },
  Voice_4964_UnlockDesc = {
    Text = "覚醒体「アイギス」獲得で解放"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "退屈してるなら、迷宮に来てあたしに「付き合って」よ。お前のつまらない人生なんて、この果てしない迷宮に使ってちょうどいいんだから。"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "雑談・迷宮について"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "ドールが同行したとき、調査員の効率は平均78.312%上がりました。加えて、多くの調査員がうつ状態に陥りました。彼女が言うには、「自分の口を制御できる人ばかりなら、世界はもっと円滑に回っていただろう」とのことです。"
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "雑談・ドールについて"
  },
  Voice_4966_UnlockDesc = {
    Text = "覚醒体「ドール」獲得で解放"
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "どうかしら？"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "降臨せよ！"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "冒険が嫌いな人なんているわけないよ！不思議な領域に足を踏み入れ、未知の世界を探索し、自分の物語を紡いでいく……なんってエキサイティングなんだろう！"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "雑談・冒険について"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "ご機嫌よう、フェイフルから参りましたニムフィーアです。自由に呼吸できる躯をくださったあなた様に……どう恩返しすればよろしいでしょう。"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "召喚"},
  Voice_4971_AwakerVoiceContent = {
    Text = "また聞こえたな、私の主を名乗る奴らの泣き喚く声が…………ああ、最高の娯楽だ。"
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_4971_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "野菜を食べないといけないんですか？偏食はダメだって、ティンクトにも言われました。でも、その色がどうしても嫌なんです……"
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "創造の神はこうおっしゃいました。「苦しみは私の創造物ではない。代行者よ、苦しみのない国を地上に建設せよ」と。この勤めを果たすのならば、私はすべてを捧げます。たとえ命を落とすことになろうとも。"
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_4973_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "すべての苦しみは、すべてを破壊する融蝕に比べれば、些細なものです。彼らの呪いを代わりに背負うことはできない。だからこそ、その痛みを和らげるために、最善を尽くさねばならないのです。"
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_4974_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "今の私ならば、彼らの体の痛みを和らげ、魂を慰めることができるでしょうか。"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_4975_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "この力で私はすべての生き物の苦しみを背負い、すべての魂を苦しみのない国へと導くのです。"
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_4976_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "この魂の暖かさ……白き炎よ、感謝いたします。 この力があれば、代行者としての務めを果たし、より多くの人々を救うことができるでしょう。"
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_4977_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "こんなに？本当にいいんですか？"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_4978_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "ふふふ……それは死ではないわ。あなたの、わたしの、この世界の……未来の姿よ。"
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "ティンクト……あの子の悲しい歌声を聞くと、無性に踊りたくなるわ……"
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "雑談・ティンクトについて"
  },
  Voice_4980_UnlockDesc = {
    Text = "覚醒体「ティンクト」獲得で解放"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "この凡庸な試練で、血脈の力を引き出せるのか？"
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "武器が手に馴染んできた。"
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "こんなことで僕が感謝すると思うなよ。僕の種族は誇り高いのだ。"
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_4984_AwakerVoiceContent = {
    Text = "攻撃は最大の防御なり。"
  },
  Voice_4984_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "あの男は……おい、待つんだ！私たちの賭けはまだ終わってないだろう？"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "雑談・他の人について"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "学院のレコーダーは大好きだけど、忘れたことをリアルタイムに思い出せる、ポータブル版があれば嬉しいなぁ……"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "虫けらだらけ。いいえ……虫けらとすら呼べないわ。ただ神の誕生に養分を提供するパン屑ね。"
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "補給を。"
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "補給を。"
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "ああ……もっと強くして。そう、もっと……"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "まだ完全に覚醒していないというのに、余裕の勝利だな。"
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "おっとっと、帽子がずれた……うん、いい感じ！"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_4992_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "「こんな力を持つ私は、本当にまだ人間と言えるのか」戦闘訓練を受けて以来、毎日そんなことを考えていたわ。世界は暗く、汚く、そして退屈だった……でも今は違う。あなたたちが現れてから、私にはこの世界がダイヤモンドのように輝いて見えるの。\nこのまま力が強まれば、いずれ人間ではなくなる、ずっとそれが怖かった。でもあなたが、私を人間の世界につなぎとめてくれるから、私はこの世界を愛せるようになった。だから、これからもよろしくね、守秘者。"
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_4993_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "ああ……あなたが戸惑うのも当たり前ね。ごめんなさい、私の配慮が足りなかったわ。パートナーであるあなたには、最初からきちんと説明しておくべきだった。\n見ての通り、私は普通の人とは違うの。きっとこれは私の生い立ちにも関係している……もちろん何度も調べようとは思ったわ。でもやめたの。だってこの学院は、私に居場所をくれたから。"
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_4994_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "白いヴェールをつけた覚醒体に会ったことはある？彼女はこの学院の土台のひとつなんだけど、正直、あまり好きではないわ。世界のことなんて眼中にないとでもいうような、あの虚ろな目。見ているとイライラしてくるの。\nはぁ？私と彼女が似ている？そう、あなたって相当目が悪いのね、医務室に行った方がいいわよ？"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_4995_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "私と教授の関係が気になる？別に秘密にしてるわけじゃないし、聞きたいなら教えるわ。デクスター教授は、私を引き取ってくれた父親みたいな人なの。\n私は学院で育って、先生たちみんなに面倒をみてもらったわ。中でもドールは一番親しい相手よ。"
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_4996_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "覚醒体事務所の手続きから、食堂がインド料理を出す日まで、学院に関することなら何でも聞いて。邪魔じゃないかって？私がそんなつれない人間に見えるの？"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_4997_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "鏡よ鏡、世界で一番すごいマジシャンはだあれ？カーシアちゃん？その通り～♪"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_4998_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "悪くないね！"
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "オールイン！"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "ああっ！"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "成功……でしょうか。あなた様のお役に立てたのですね。"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "無駄だ！"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5004_AwakerVoiceContent = {Text = "ぐっ！"},
  Voice_5004_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "それっ！"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "一緒にここを賑やかな海にしようよ！"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "護衛は必要か？君の求めるものが正義である限り、俺も力を貸そう。"
  },
  Voice_5007_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5008_AwakerVoiceContent = {
    Text = "燃えないように……"
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "燃えないように……"
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "あら、ハグして欲しいの？"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "この体にまとわりつく鎖を見ろ。これは飾りではなく、警告だ。裏切られた怒りを、踏みにじられた痛みを、決して忘れるなという戒めだ。"
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "学院の過去が知りたいなら、資料館に行くといいわ。\n……え？まさか、全部私に説明しろっていうの？学院の前身も含めて、300年もの歴史があるのよ？"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "あたしを挑発してるの？やってやろうじゃない！"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "深海はあなたを永遠の眠りへ誘います。"
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "深海はあなたを永遠の眠りへ誘います。"
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "永劫の緑炎、死告の舞いを、ここに！"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "永劫の緑炎、死告の舞いを、ここに！"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "灯台のようなあの女性……永夜の恒星間航行に、あのような眩い灯火を見つけられていれば、迷わずに済んだのでしょうか……"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "雑談・ファロスについて"
  },
  Voice_5018_UnlockDesc = {
    Text = "覚醒体「ファロス」獲得で解放"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "新任守秘者さん、まずは見せてもらえる？\nわたしが実験室を出るほどの価値が、あなたにあるのかを。"
  },
  Voice_5019_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5020_AwakerVoiceContent = {
    Text = "お前はわたくしの下僕、そして下僕の役目はわたくしが欲しいものを即持ってくること。わかったわね？な、なによ、下僕の分際で、ご褒美をねだるつもり？はいはい、やればいいんでしょやれば！"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "ああっ！"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "この一撃で雪辱を晴らします……！"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5023_AwakerVoiceContent = {Text = "あら？"},
  Voice_5023_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "ああっ！"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "我が血で新たな命を育みましょう。"
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "欲すればまず与えよ。"
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "危ない！"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "来ないで！"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "満月の夜の金色の月明かりが好きよ。神秘的で優しい感じがするから。風が吹けば、海がきらきらと光って、まるで夢のようなの。"
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "私たちの故郷に、融蝕が起きてさえいなければ、ティンクトと離れ離れになることもありませんでした……だから融蝕は嫌いです、野菜よりも嫌いです。"
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "この先にあるのが宝か、それとも港か、私にとって大した違いはないわ。私の使命は航海の安全を守ることだから。"
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5031_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "天国の鳥の跡を辿って、青い空の彼方を目指すの。"
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5032_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "ときどき水平線を眺めながら、その彼方にある風景を想像するの。そこにあるのは、どんなに近づこうと絶対にたどり着けない大陸。いつか一緒に見にいきましょう。"
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5033_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "ご好意ありがとう。たとえ狂暴な嵐の中でも、全力であなたに祝福を授けるわ。"
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5034_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "水兵たちの歌が聞こえる、ああ、懐かしい故郷の匂い。"
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5035_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "あなたは私を救いにきた、そうでしょう？腐れ果てたこの世から、魂を焦がすこの憎しみから、永劫に続くこの業火から……救ってくれるのよね？"
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "不届きもの！"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "指名料として受け取らせていただきますね。"
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5038_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "懲らしめてあげる！"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "ぐうっ……！"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "くうっ！"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "うああっ……！"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "鼠の実力を見せてやる！"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "鼠の実力を見せてやる！"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "賽は投げられた、ってな！んじゃ、行くとするか！"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "黒く血に染まったこの足で、輝かしいバレエの世界に再び立つことが出来るなんて。……すべてあなたのおかげよ。これからも私の踊りを見守ってね、守秘者。"
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5047_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "どんなに藻掻いても、運命には逆らえない。けれど、その瞬間の光だけは、永遠になるの。"
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5048_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "ねぇ、敗北者にはどんな罰を与える？"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "この胸の憧れが消えようと、私はあの白鳥を演じきるわ。"
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5050_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "目を閉じて、何が見えたかを教えて。私がイメージしたのは、無垢な月明りと、穏やかな湖……"
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5051_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "どうして私たち姉妹には、破滅と悲運を招く災厄がつきまとうのでしょうか？"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "私を拒まないで……"
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "私の愛を受け取って。"
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "かなり楽になりました、ありがとうございます。"
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "くぅ……"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "お返しにあなた様に、淡い紫色の睡蓮を贈りたいです。"
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "私も、強くなれるでしょうか。"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "やります……"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5060_AwakerVoiceContent = {Text = "ぐあっ"},
  Voice_5060_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "この足が気になるのか？君がそんなことにまで興味を持つとは思わなかった。\nこの怪我は生前、戦場で負ったものだ。ああ、気にする必要はない。覚醒体になってからは、戦闘に支障はないしな。\n痛み？……そうだな、当たり前になっていて、痛みについて考えたことがなかった。"
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5061_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "シルヴィアが、俺の精神状態について尋ねてきた。彼女を呼んだのは君か？時折幻肢痛がするのは認めるが、しかし、俺の気持ちを気遣う必要はない。俺は君の刀だ、君の利刃だ。正義のために戦えるのだから、これしきの痛みは、何の影響も及ぼさない。"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5062_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "お茶会お茶会～♪ティーパーティーしよう！シルヴィアから紅茶とデザートをたくさんもらってきたんだ！うん、ファッターワッケンを踊ってあげたお礼にね♪"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "自分のことを俺と呼ぶ理由か？話してもかまわないが、そんなに俺が気になるのか？ただおしゃべりをしたかっただけ？\n……そうか、わかった。軍隊では、性別で仲間を区別することはない。男ばかりの環境にいたからな、時間が経つにつれて、この話し方が身に付いたんだ。"
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5064_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "おもしれーな……力を手に入れた俺は、お前をズタズタに引き裂くかもしれないぜ、怖くねぇのか？"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "俺様の守秘者らしく、毎日頑張ってんじゃねえか！褒めてやるぜ。"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "雑魚どもの喉を引き裂きたくてたまんねぇ。"
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "ダンスは純粋なものよ。言葉は誤解を招くけど、踊りはまっすぐ心に届く……あなたもそう思うでしょう？"
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "雑談・ダンスについて"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "海には嫌いな一面もあるわ。なぜなら海はわたくしの愛するものをすべて呑み込んでしまったから……"
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "忘れても失っても、今度こそは帰るんだ！"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "忘れても失っても、今度こそは帰るんだ！"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "危ないですから、これ以上近付かないでください。"
  },
  Voice_5072_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5073_AwakerVoiceContent = {
    Text = "好きに触れ。これはコロシアムにいた頃の傷、男の勲章だ！"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "くうっ！"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "いたたた！"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "くうっ！"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "くうっ！"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "体から何かが湧き出る感じがするの、これが霊知啓発なのね。"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5078_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "これは新しい技術か？義肢がずいぶん軽くなったようだ。"
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5079_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "潮風の匂いがするわ、もうすぐわたくしの国へ着く。"
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5080_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "あの世へ旅立った同胞は、この光で帰り道を見つけることができるかしら。"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5081_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "何千年、何万年もの間、あなたを探し続けた気がするの。あなたが彼岸にたどり着くまで、わたくしがあなたを助けましょう。"
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5082_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "わたくしは祖国と、あなたのためだけに輝く……"
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5083_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "細かい砂を包んだ風が、わたくしの足を撫でていくのを感じたわ。"
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5084_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "お力添えはここまでですわ。あまり欲張りすぎるのも、よくありませんよ？"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5085_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "見返りは何をお望みですか？私にしてほしいことは、戦うことのみですか？"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5086_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "愛の首、怨みの首、憎しみの首、欲望の首……あらお客様、いらしていたんですか？"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5087_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "取引ですので、ただで頂くわけにはいきません。当店で何かお選びになりますか？"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5088_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "喜び、楽しさ、絶頂の快感……余すことなく伝えるわ。だからお返しに、あなたの欲望も正直にさらけ出してちょうだい？"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "雑談・守秘者について2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "私は母樹、母樹は私。樹の乳は私の血脈の中を流れ、樹の意志は私の意識の中を彷徨っているわ……"
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "雑談・豊穣母樹について"
  },
  Voice_50899_UnlockDesc = {
    Text = "「調査」第7章クリアで解放"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "裏切りの代償を払え！"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "鍵塚を見まわしていたら、あなたの墓石が見えたわ……私のミイラも、いつかそこに埋葬されるかしら。あら、されないの？残念。"
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "雑談・鍵塚について"
  },
  Voice_50900_UnlockDesc = {
    Text = "「調査」第7章クリアで解放"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "あのオオカミさんね……彼とNの間には、なんとも言えない関係があるの……"
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "雑談・ライカーについて"
  },
  Voice_50901_UnlockDesc = {
    Text = "覚醒体「ライカー」獲得で解放"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "近づいて、抱きしめて、味わって……私を忘れないで。"
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "雑談・守秘者について3"
  },
  Voice_50902_UnlockDesc = {
    Text = "「調査」第7章クリアで解放"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "あの子、努力家で用心深いのはいいけど、度を越してるのよね。あら、もちろん責めるつもりはないわよ。彼女がいなければ、あの気まぐれな種族はとっくに滅びていたでしょうし。"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "雑談・アルバについて"
  },
  Voice_50903_UnlockDesc = {
    Text = "覚醒体「アルバ」獲得で解放"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "黄砂に生まれ、また黄砂に還る。この短い旅の間に、何を残し、何を蒔くべきかしら。"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "雑談・砂漠について"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "すべては愛から生まれるの。愛は最初の種。愛があってこそ、天をつく巨木が育つのよ。"
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "雑談・欲望について"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "あら、かわいい鼠ちゃんが通り過ぎたわよ。鼠は肉の味が好きな動物だって聞いてるけど。ここにいる鼠ちゃんは、まだ赤ん坊なのよね……"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "雑談・ジェンキンについて"
  },
  Voice_50906_UnlockDesc = {
    Text = "覚醒体「ジェンキン」獲得で解放"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "彼らは私の骨肉と血を受け継ぎ、滔々と流れる川の水でヴォルムワヒを豊かにした……これからは、あなたに血脈を守ってもらうことになりそうね……"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "雑談・アランについて"
  },
  Voice_50907_UnlockDesc = {
    Text = "「調査」第7章クリアで解放"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "蜘蛛……蜘蛛ね。ふふ、私は蜘蛛が好きよ。びっしりと生まれた子供たちがすぐさま這い回る。あの繁殖力と生存力はうらやましいわ……"
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "雑談・アグリッパについて"
  },
  Voice_50908_UnlockDesc = {
    Text = "覚醒体「アグリッパ」獲得で解放"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "母樹の血を引くものは皆我が子、種を飲んだあなたもよ。"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "雑談・子孫について"
  },
  Voice_50909_UnlockDesc = {
    Text = "「調査」第7章クリアで解放"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "店で取り扱っている商品ですか？それは……すべての欲望を満たすためのお品。お望みのものを何から何までも備えておりますわ。……ただ、相応の対価をお支払いいただきますけど。"
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5090_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "まあ、一度負けたことは認めざるを得ないわ……でも幸い、彼女に選ばれたあなたも、母樹の乳を飲んで、私の血と種を新世界に連れていってくれるのよね。"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "雑談・タヴィについて"
  },
  Voice_50910_UnlockDesc = {
    Text = "覚醒体「ラモンナ」獲得で解放"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "あいつは、得体の知れない怪物よ。私はよく知っているの。同じく創世神から生まれたから。彼の甘い言葉を鵜呑みにしないこと。私を悲しませたくなければ……ね？"
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "雑談・Nについて"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "意識があるものには、欲望がある。機械の生物だって例外じゃないと思わない？"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "雑談・エリカについて"
  },
  Voice_50912_UnlockDesc = {
    Text = "覚醒体「エリカ」獲得で解放"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "裏切りの代償を払え！"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "不思議の国へ、ようこそ～！"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "ぐぅ……っ。"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "彫むことの苦しみと、生まれ変わるときの灼熱感はよく似ているわ。でもね、永遠なるヴィーナスの前では些細なことなの。"
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5094_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "口にできない言葉は、作品で伝えるの。"
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5096_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5097_AwakerVoiceContent = {Text = "ああっ"},
  Voice_5097_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "眠れる主は私の耳元で囁き、深海の廃墟は目の前で組み替えられる……何度も夢にみた光景が、ようやく現実になるのね。"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5098_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "アトリエを用意してくれてありがとう。ここにある作品の一つ一つ、ノミの一本一本が、太陽の光を浴びて金色に輝いているわ。ああ！春の色は金色なのね！"
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5099_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "性格は違うけれど、あの子のことは気に入っていますよ。彼女には、あらゆる逆境やしがらみから抜け出す勇気があるんです。私にもし彼女のような勇気と強さがあれば、海に身を投げたりしなかったかもしれません……"
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "雑談・マーフィーについて"
  },
  Voice_5100_UnlockDesc = {
    Text = "覚醒体「マーフィー」獲得で解放"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "マダム・レッドは、僕が今まで仕えてきた方々とは、一味違います……べつに嫌いなわけじゃありません、ただ、すこし苦手なんです……"
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "雑談・ソレールについて"
  },
  Voice_5101_UnlockDesc = {
    Text = "覚醒体「ソレール」獲得で解放"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "足掻きなさい。"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "狂気を胸に！"
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "狩り尽くす！"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "ここまでしなくてもいいのに……"
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "心って、永遠に満たされない底なしの深淵みたいね。"
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "痛くも痒くもなかったけど……一応ありがとう。"
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "あ……私に声をかけているの？ごめんなさい、マストで見たことを思い出そうとしていたの。質問をもう一度言ってみて？"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "雑談・過去について"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "ご主人は、リリーのご主人で、お母さん。"
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "隙あり！"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "見切った！"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "準備——"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5113_AwakerVoiceContent = {Text = "はっ！"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "もっと強く～。"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "熱々のラブ♡"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "融蝕現象について……詳細は語れぬが、一つ教えてやろう。お前たちが想像するよりも遥か昔に、すでに融蝕は現れているのだ。"
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5118_AwakerVoiceContent = {
    Text = "本気を出すときが来たようだな。"
  },
  Voice_5118_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5119_AwakerVoiceContent = {Text = "はい。"},
  Voice_5119_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "行きます。"
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "ふん、お飾りの姫がまた泣いてるぜ。ミルクが口に合わないのか？それとも子守唄が耳障りか？"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "雑談・マーフィーについて"
  },
  Voice_5121_UnlockDesc = {
    Text = "覚醒体「マーフィー」獲得で解放"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "うぅ……こういうの、向き合いたくない……"
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "これがあなた様への恩返しです。"
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "骨まで蝕む炎のような灼熱……力がみなぎっているのを感じます。"
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "あの…ごめんなさい！暴れないでください！"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "この暖かさには、手が届くのですね……"
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "中庭の薔薇が咲いています。"
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "よくやったわ。まだ戦える？"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "騎士には本来の形というものはありません。忠誠、勇気、そして美徳が、騎士を作りあげました。僕の武器も、守る意志があるからこそ、重剣の姿になったんです。"
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "雑談・騎士について"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "ジェンキン、ダイアナ、マイク、テューグ、ブラウン……あっ！ご、ごめんなさい、独り言です！えっ、どうして名前を呼んでるか、ですか？それは、アイギスがみんなのことを、忘れたくないから……"
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "雑談・友達について"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "近寄らないで！"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "嫌いよ！"
  },
  Voice_5132_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5133_AwakerVoiceContent = {
    Text = "科学の力を畏れなさい。"
  },
  Voice_5133_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5134_AwakerVoiceContent = {
    Text = "科学の力を畏れなさい。"
  },
  Voice_5134_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "ラ～ラララ～……お呼びいただき、ありがとうございます。歌声を捧げる必要がございましたら、予めお声がけくださいませ。"
  },
  Voice_5135_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5137_AwakerVoiceContent = {
    Text = "それは、血管を駆け巡る黒い粘液、あらゆる嘆きを消滅させる究極の力！「私」はここで生まれた、すべてを破壊するために生まれたの！アハハハハ！"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "やあ！なんだい？賭け事かい？……はぁ、ただの事件じゃないか。私はごめんだよ、運が逃げてしまうからね……"
  },
  Voice_5138_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5139_AwakerVoiceContent = {
    Text = "理論の授業は退屈ね。授業中はいつも、最後の列でこっそり調査ファイルを読んでるわ。これ、ドールには内緒よ。"
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "復讐はまだ終わってない！"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "悪の報いを味わえ！"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "ジュリエットも黒き苦難の被害者に過ぎませんので、責めるつもりはありません……ですが、彼女は私の言葉を聞きたくないようです。白き御使いよ、彼女に伝えてくれませんか？"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "雑談・ジュリエットについて"
  },
  Voice_5142_UnlockDesc = {
    Text = "未実装の音声"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "ゆっくり。"
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5144_AwakerVoiceContent = {
    Text = "こっち。"
  },
  Voice_5144_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "ちょっと！ベタベタ触らないで！服が乱れちゃうわ！まあ、わたくしは心が広いから、許してあげるけど。"
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "いらん！"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5147_AwakerVoiceContent = {Text = "チッ！"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "あなたが私を闇から目覚めさせたあの日、私はあなたがすべてのものを、融蝕という絶望から救い、無垢の浄土に送ることができると確信しました。その日が来るのを楽しみにしています、私の白き炎よ。"
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "雑談・守秘者について・Ⅰ"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "血の匂いだ……"
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "ターゲットはどこ？私を呼び覚ましたお礼に、相手を殺してあげる。"
  },
  Voice_5150_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5151_AwakerVoiceContent = {
    Text = "カーシアの帽子は待ちくたびれているぞよ！"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "わたくしは、神以外の存在にときめいてはいけないのです……しかしあなた様の体温は……"
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "なんだ、やるのか？"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "汚らわしい……"
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "許さない。"
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "エリカは現在、正常に作動しており、大学の電気設備との接続も良好です。寮の電灯をつけますか？"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "雑談・エリカについて"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "いよいよ食事の時間ね、ふふふ……"
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "あのつばの広い紫の帽子をかぶった女をステージに近づないで！理由なんてどうでもいいの！帽子からベタベタの脳みそが出てくるのを見たくなければ、ちゃんと遠ざけてよ！"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "雑談・ダフォダイルについて"
  },
  Voice_5159_UnlockDesc = {
    Text = "覚醒体「ダフォダイル」獲得で解放"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "背中を他人に預けるなんて……君はずっとそうしてきたの？……甘い、甘すぎる。"
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "憎しみは、たとえ薄れることがあろうと、決して消えることはない……"
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "覚醒体？うーん……そうそう！朝七時は一番があたまが覚醒する時間だよ！明日は早く起きて、海に貝殻を拾いに行こう！"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "雑談・覚醒体について"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "永遠の命を与えよ！"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5164_AwakerVoiceContent = {
    Text = "はあっ！"
  },
  Voice_5164_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5165_AwakerVoiceContent = {
    Text = "はあっ！"
  },
  Voice_5165_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "ご、ごめんなさい、ここにいるとあなたの邪魔ですよね、今すぐ消えますから！"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5166_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "居場所を提供してくれたことには感謝するわ。けど私のステージを期待してるなら、諦めて。私にはもう、舞台に立つ資格はないの。"
  },
  Voice_5167_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5168_AwakerVoiceContent = {
    Text = "そばに居させてくれて、ありがとう、です。お礼に何でもしますから、言ってください。お、お茶とか、淹れましょうか……？"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5168_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "ここは暖かいから、離れたくありません。一人でいる時は、暗くて寒くて怖いんです……"
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5169_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "アイギスにも……普通の暮らしができるでしょうか。心の準備だってまだなのに、あなたはアイギスを、やさしく受け入れてくれて……あの、これからもよろしくお願いします、守秘者さん。"
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5170_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "ああ、思い出した、思い出したぞ！汚い人間の血のせいで……僕は生まれ変われなかった！なぜだ！僕のエラはなぜ動かない！？なぜだ……！"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5172_AwakerVoiceContent = {
    Text = "たこ焼き、たこの煮込み、たこの鉄板焼き……一部の奴からみれば、俺様は神を冒涜してるのかもしれねぇが、たこは本当にうまいぜ！はははははは！"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "俺はなんだ？虫けらでも星々でもない、俺は……ユウハシュだ！殺したい……殺させろ……！"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5173_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "深紅の胴体、脈打つ触手、胸元の貪欲な口……くくく、誰かの喉を引き裂きたくて待ちきれないな！"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5174_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "ははははは、これはたまらないな！もうちょっとやってくれよ……二倍、いや十倍はくれ！"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5175_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "最後まで耐えて見せます。"
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "この奇妙な感覚、悪くないな……ウィザードのベラドンナよりしびれるぜ。"
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5177_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "仲間だ？ふん……俺様に仲間は必要ねえ。二度も過ちを犯してたまるか。"
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5178_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "俺様が力を貸したのは、お前がそれに相応しい力を見せたからだ。この先、お前が強さを失ったときは、容赦なくその首を切り落とす、わかったか。"
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5179_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "お前の目には、野望と欲望の烈火がメラメラと燃え上がってやがる。やっぱりお前と俺は同類だな！"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5180_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "アホウドリを知ってるか？奴らは人間なんざまるで眼中にねぇ。いつだって高く羽ばたいて、嵐の挑戦を迎え撃つ。だが奴らは地面に降りると、嘲りの声の中で、その巨大な翼がかえって悲しい足枷になるんだ。\nまあ、別に深い意味なんてねぇ。お前といると気が楽で、つい色々話しちまうな。"
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5181_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "時代は本当に変わったのかもしれねぇな。今じゃ、弱ぇ奴が空で羽を広げることも、嵐に打ち勝つこともできる。\nなあ凡人、お前が歴史を書き換える日を待ってるぜ。その時は喜んで、お前の刃になってやるよ！"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5182_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "転換率が低すぎるわね、一から勉強し直す必要があるわ。明日わたしのオフィスに来るように。"
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "もう一人のドールとは会ったか？「世界の真実」というものは、あの理性の塊だったドールすら別人に変えてしまった……結局はあなたも私も、ああなるのだろうか？"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "雑談・@2について"
  },
  Voice_5184_UnlockDesc = {
    Text = "覚醒体@2獲得後に解放"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "ご主人……命令して欲しい、命令をください。"
  },
  Voice_5185_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5186_AwakerVoiceContent = {
    Text = "機体性能が向上しました。"
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "んふふ～♪"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "遊ぼう～！"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "仲間をもっともーっと！"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "ごめんなさい……私、揺りかごから出られなくて……みんなの視界を遮ってしまうので、教室の一番後ろにいさせてください。"
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "なんですって！コンスタンティノープルのカーペットも、セイロンティーも、アンダルシアのチュロスも買えなかったの！？くぅ……あの女はいつも簡単に手に入れてくるから、てっきりどこにでもあるものかと……"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "我の最初の姿とは程遠いな。"
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5194_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "あなたのような才能ある人が、そんなに焦ってはいけませんよ。"
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "強くなっても、この獣の姿は変わらぬ。何せこいつは、我の力が具現化したものだからな。"
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5196_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "混沌の海に戻った気分だ、悪くないぞ。"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5197_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "ここまでよくぞ頑張った、同行者として認めてやってもよいぞ。"
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5198_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "迷路の壁は打ち壊せばよい、力の壁もな。"
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5199_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "食べ物を粗末にするのは、だめ……食堂の椅子を潰すのも、だめ……わかった、もうやらないです。"
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5200_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "お母さんって呼んでもいい？"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5201_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "ご主人、ご命令は？\nあいつらと一緒に歩くの、みんな怖がる？わかった、隠す。"
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5202_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "覚醒体になるってこういうことだったんだな。"
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5203_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "お母さん、隣で寝てもいい？一人でいると、怖い夢をみるから。リリーの手や足がもげて、すごく痛い……"
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5204_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "わあ！カレンに期待してくれて、ありがとうございます！カレンなんてただの卑しい侍女ですのに……"
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5205_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5206_AwakerVoiceContent = {
    Text = "夢のようです。"
  },
  Voice_5206_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "ちょうど彫刻に使う素材が欲しかったの、新鮮なのが一番よね、ふふ。"
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "お静かに。"
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "ふぅ、頑固者は無駄なことばかりで困る。"
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5209_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "ここにきて、ようやく貴様の意図がわかってきた。構わん、続けるがよい。"
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5210_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "貴様の決心はわかった。再び眠りにつくまでは、余も人の子が運命に抗う様を見届けよう。だが今は、少し休む時間がほしいのじゃ。"
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5211_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "天命に従ってなにが悪い？なぜ運命に逆らう？"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5212_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "願いを叶えるため、ここまでするとは……"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5213_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "ああもう、うっさいわね！あいつのことでわたくしを煩わせないでちょうだい！ふぅ、まあいいわ……どうせ暇だし、付き合ってあげるわよ。感謝しなさい！"
  },
  Voice_5214_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5215_AwakerVoiceContent = {
    Text = "融蝕……あの汚く黒い液体は常に余の夢を侵食する、ゆえに煩わしいのじゃ。"
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "権力は諸刃の剣だと、もちろん知っています……ただ、目を覚ますのが遅すぎました。わたくしが手を離したとたん、権力は襲いかかり、わたくしを引き裂くのです……最初からあなたのようにしっかりしていれば、悲惨な結末を迎えることはなかったのでしょうね。えっ？ラウンジでサロンを開いてもいいのですか！？ ありがとうございます……このお礼は、あなたにお仕えするだけでは足りませんね。どうやってお返しされたいですか……？"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5216_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "ああ……本当に頑固なお客さまですね。一体どうおもてなしすれば、特権を譲ってくださるのですか？権力は災いをもたらすという、単純な道理がわからないあなたではありませんよね。"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5217_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "サロンが始まる前に昔話をひとつ、いかがですか？田舎娘が権力を手にした話ですけど……どこから話しましょうか。親に売られて、老人と結婚させられそうになったところから？それとも、貴族の庭で花開いたところからか……"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5218_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "以前はゲストから、「マダム・レッド」という名で呼ばれていました。 もちろん、わたくしを「ソレール」と呼んでくださってもかまいませんよ。あなたは一番特別なお客さまですから……"
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5219_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "サロンのホストとして、すべてのゲストに喜んでいただくことがわたくしの務めです。"
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5220_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5221_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "主君？僕の立ち姿がいけなかったのでしょうか。"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5223_AwakerVoiceContent = {
    Text = "不運だ……！"
  },
  Voice_5223_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "ぐあ……！"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5225_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "この感覚、覚えてるぞ。栄光のときがまたやってくる……"
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5226_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "エラはまだ生えてこないが、もうそのことで悩むつもりはない。このヒレでお前を守る盾となろう、守秘者。"
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5227_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "お前……他の人間より辛抱強いところがあるんだな……僕にこれほど資源を注ぎ込むなんて……、僕のことを、本当に蔑んでいないのか？"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5228_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "なっ？儀式はもう終わりなのか？なぜエラはまだ生えてこない！くそ！くそ！くそ！"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5229_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "ああ、あの声がまた僕を呼んでる……深海の底に響く、美しい声が！"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5230_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "は・ず・れ♪"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "美術家サンガー、シディの街から、あなたにこの腕を捧げに来たわ。あなたはまるで磨かれていないダイヤの原石のようね。"
  },
  Voice_5232_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5238_AwakerVoiceContent = {
    Text = "悪い子たち、集まって～。"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "真の芸術に説明はいらないわ。"
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "真の芸術に説明はいらないわ。"
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "オレッタも、力になれるかな？"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "角笛を鳴らせ！"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "犠牲を惜しむな！"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "陽の光を浴びるって、心地いいんだね。涙が出るぐらい、優しい温もり。"
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5244_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "感謝を示すために……私の痛みの奥深くに、あなたの寝殿を築くよ。"
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5245_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "お兄ちゃんと私の体が、深いところまで溶け合ってる……"
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5246_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "あなたが思うよりも、私はタフにできているから、私を使うときはもっと力強くでも大丈夫、遠慮はいらないよ。"
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5247_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "私の錯覚なの？血への渇望が少しよくなったみたい。"
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5248_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "入学前からあなたとの出会いを楽しみにしていたの。実際、私たちっていいコンビだと思わない？"
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "様になっていませんよ。"
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5251_AwakerVoiceContent = {
    Text = "やぁっ！"
  },
  Voice_5251_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5252_AwakerVoiceContent = {
    Text = "アハハハ！"
  },
  Voice_5252_AwakerVoiceTitle = {
    Text = "攻撃・躁狂"
  },
  Voice_5253_AwakerVoiceContent = {
    Text = "あぁ……"
  },
  Voice_5253_AwakerVoiceTitle = {
    Text = "攻撃・抑鬱"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "思う存分痛めつけて！"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "アイギスは怖いんです。あの、みんなが怖いんじゃなくて、またみんなに悲しい思いをさせちゃわないかが、怖いんです。"
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "この時代の絵本は、昔のよりもずっと面白いですね！あ、あの！誤解しないでください、もう絵本を読みたがるほど子どもじゃありませんから！"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "思う存分痛めつけて！"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "ふう……アイギスは、皆さんにご迷惑をかけなかったでしょうか。"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "お前はいつまでもたっても、そのおかしな信頼をもって私の側にいる……お前にだけは、利用されるのも悪くはない。……だが覚えておけ。私は裏切りを許さない。たとえお前であろうと、いや、お前だからこそ、決してな。"
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5259_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "あのとき、あいつらの屍を十字架に縛りつけて、晒しものにしてやればよかった！私を裏切った奴、踏みにじった奴、侮辱した奴、誰一人逃がしはしない！"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5260_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "そう、私もかつてはあいつらに尻尾を振っていた。それは否定しない。だからこそ、私の無知を利用したあいつらに、それなりの代償を払ってもらったのさ。"
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5261_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "少し親切なふりでもすれば、私がその口車に乗って枷を掛けられ、喜んでお前のおもちゃになるとでも思ったか？"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5262_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "私を道具とみなして利用する奴は、漏れなくこの手で冥界に送ってきた。……お前も送ってやろうか？"
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5263_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "あの…ごめんなさい！暴れないでください！"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "触れるな！"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "無礼者！"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "抵抗はおやめ、享楽と夢の宴へようこそ。"
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "すべての彷徨う者よ、死の都へお行き。"
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "アイギス、が、がんばります！"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "あの……まだ力の制御ができていないので、うっかり精気を吸い取ってしまうかもしれません。揺りかごに、手を入れないでください。"
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "わたしたちがこうして話している間に、彼女がまたミスをしないといいんだけど。次に爆発を起こしたら、今度こそ実験室がなくなっちゃうわ。彼女はかわいいけど、そういうところが憎たらしいのよね。"
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "雑談・エリカについて"
  },
  Voice_5271_UnlockDesc = {
    Text = "覚醒体「エリカ」獲得で解放"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "腕が言うことを聞かないの！いつも髪を引っ張られる。自分の腕すらコントロールできないなんて、私は本当にダメな人間ね……もういっそのこと……"
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "雑談・自分について"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "私をお導きいただき、ありがとうございます。ようやく、ファイントの選択が理解できました。私が当然だと感じていたことが、姉さまにこれほどの負担をかけていたなんて……これからは、自分のために生きてみようと思います……"
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5274_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "長い長い年月の中、ファイントと私の心には、お互いしかいませんでした。けれど今は、新たに大切に思う方ができた……守秘者様、前言を撤回させていただけますか？貴方様は、私の歌声やドレスばかりを気にする方々とは違い、私そのものを見つめてくださいます。ですから私も、貴方様のことを見つめていきたいのです。"
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5275_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "余の夢で眠る星々よ、目覚めて神の国を示せ！"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "いつもこのドレスを着ている理由、ですか？これは、いつでも貴方様に声を捧げられるように、です。"
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5277_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "私自身がやりたいこと？……申し訳ございません、よく意味が分からなくて……実はファイントからも何度か、同じことを聞かれています……私はただ、姉さまが一日でも早く治ればと、そう願うばかりです……"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5278_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "荒星にいた頃、さる高貴な方々が私たち姉妹を哀れみ、生きるための資源を分け与えてくださいました。最後も、一人だけとはいえ、荒星から脱出する機会を与えてくださり……あの方々は私の恩人です。ここに居場所をくださった、守秘者様のように。"
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5279_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "優しいあなたは、アイギスに居場所をくれました、だから、何でも言うことを聞きます。でも、アイギスが無能じゃなかったら、もっとあなたの役に立てるのに……"
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "儀式の場所は予約したの？アイズルワースより小さい場所じゃないでしょうね？"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5281_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "よ～し！俄然やる気が出てきました！一日で20部屋は掃除できちゃいますよ～！"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5282_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "フン～フン～フン♪　これは湖と同じくらい歴史の深い「私たち」の音楽なんです。さあ、ご主人様も一緒に踊ってください！カレンの声が「神様」に奪われる前に……"
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5283_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "ご主人様！カレンの声が……消えていく……たす……けて……"
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5284_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "カレンの視力が上がりましたよ……！ご主人様、また髪をとかすのを忘れましたね？"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5285_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "たとえ強くなっても、カレンは復讐なんてする気ありませんよ。歌を歌ったりダンスを踊ったり、パーティを楽しむことが、カレンの一番の望みなんです！"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5286_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "私は、すべてを破壊されても生き残るために、あまりにも多くの人に、精神と血を与えてしまった。今の私の力は、この意志を受けたときに比べば、とてもちっぽけなの。"
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "雑談・過去について"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "教棟で俺を探しても無駄だ。あんな本の虫だらけの臭い場所に、一秒たりともいられるものか。"
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "逃げないで。"
  },
  Voice_5289_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5290_AwakerVoiceContent = {
    Text = "わたくしの祖国は「神」を信じているから、王も「神に通ずる人」が選ばれるわ。"
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "雑談・永遠の国について"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "あなたのところには才能のある人が集まりますね。然るべきときに、盛大なサロンを開きましょう。心配なさらないで、そのときはあなたにも招待状を届けますから。"
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5292_AwakerVoiceContent = {Text = "さぁ！"},
  Voice_5292_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "仲間がたりないよ～……"
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "剥き出しの殺意で恐怖しか与えないあいつと違って、あたしの調教は甘～い痛みと、愛に満ちているわ。"
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "雑談・ワンダについて"
  },
  Voice_5294_UnlockDesc = {
    Text = "覚醒体「ワンダ」獲得で解放"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "これで終わりだなんて思わないで！受けた屈辱は一つ残らず返してやるわ！"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "あなたの手は、あなたの魂と同じくらい暖かい。白き炎よ、私に触れてくれてありがとう。"
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "教室でトランプして何が悪いの？机も人もカードも揃ってるし、やらない方がおかしいでしょ！"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "やめて！"
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "抵抗するな！涙を流すな！命を惜しむな！"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "抵抗するな！涙を流すな！命を惜しむな！"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5302_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5302_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "ああ……！"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "いやっ……！"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "ああ……っ！"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "神の光を！"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5307_AwakerVoiceContent = {
    Text = "祈りが届きますよう！"
  },
  Voice_5307_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "弱虫がいくら集まっても、強くはなれないわ……ハァ……"
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "戦争とは痛みを伴うものだ。それに耐えることは、戦士の義務と言えるだろう。たとえ手足のすべてを失おうと、俺は君のため、そして正義のために戦う。"
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "これが神への貢物なの？"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "これで未来を変えられるとでも思うの？"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "神は……わたくしの中に宿る。"
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "ふん、随分気が利くじゃない。"
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "下僕が主に貢ぐのは当然でしょ。"
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "必死にあたしの機嫌を取る様子は、なかなかかわいいじゃない。"
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "ブラウニー、キャラメルプリン、ザッハトルテ、チョコレートムースケーキ、クッキー……全部テーブルに用意して！"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5318_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "ねぇ、ちょっと確認して。わたくしのスカートはどう？シワやほつれがあったりしない？……なによ？なにか不満でもあるの？"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5319_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "ようこそ、霊知啓発の最終儀式へ……すべてはわたくしが丹念に準備したものよ。まあ、守秘者にも少しだけ手柄があるわ……"
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5320_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "テーブルクロスはレースのあるものを、鉢植えは赤いオリヅルランを用意して。ほら早く！"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5321_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "早くゲストを呼びに行って！どうしてこれしきのこともできないわけ？"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5322_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "逃げ場はないぞ！"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "逃げ場はないぞ！"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "あなた様の期待に裏切らないよう、日々精進してまいります。"
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5325_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "あの女、ちょっと好きだな……、あたしとはあれが合いそう。あれってなんだっけ……えーっと、そう！趣味！同じ趣味がありそうね！"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "雑談・ワンダについて"
  },
  Voice_5326_UnlockDesc = {
    Text = "覚醒体「ワンダ」獲得で解放"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "無礼者！"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "無礼者！"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "骸となれ。"
  },
  Voice_5329_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5330_AwakerVoiceContent = {
    Text = "砕けなさい。"
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "現実を突き抜けろ！"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "近い将来、海を渡る予定があるの？その、わたくしの同行を許可してもらえないかしら？海に行ければそれだけでいいの……"
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5332_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "まだわたくしを信じてくれるのなら、わたくしがあなたの道しるべとなりましょう。けれど、ひとつだけ伝えておくわ。わたくしはその簡単な仕事で、過ちを犯したことがあるの……"
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5333_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "海に出てみたくはない？今日のグラフを見ると……南緯47度9分、西経126度43分、ここがいいでしょう。"
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5334_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "わたくしは過去に数々の災厄を引き起こし、ある文明を滅ぼしかけた……故意ではなかったと言っても、もう遅いのでしょうね。"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5335_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "わたくしは永遠の国の入り口に立ち、帰る人の道案内をする者。そんな役目をもつわたくしが、祖国の場所を忘れてしまうなんて……あなたは……わたくしの灯台になってくれるの？"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5336_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "星団よ。"
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5338_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "濃霧よ。"
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5340_AwakerVoiceContent = {
    Text = "平気よ。"
  },
  Voice_5340_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "加護を与える相手は選ばないけれど、あの女は例外。もし可能なら、別のルートを手配して。"
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "雑談・ミリアムについて"
  },
  Voice_5341_UnlockDesc = {
    Text = "覚醒体「ミリアム」獲得で解放"
  },
  Voice_5342_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "それで終わり？"
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "手を放せ。"
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "海底宮殿に戻るまでの間、軟弱なお前に少しだけ、深海の力を貸してやっているだけだ。"
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5346_AwakerVoiceContent = {Text = "来い！"},
  Voice_5346_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "好きなもの？私は痛くするのも痛くされるのも大好きよ。赤く腫れ上がる肌に、快楽と苦痛の入り混じる呻き声……ゾクゾクしちゃう。痛みって、最も原始的で現実的な欲望だと思わない？"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "かくれんぼスタート！"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "オレッタの仲間になって！"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "あのお姉ちゃん、ずっと怖い目でリリーを睨んでる。でも、なんとなく好き。お母さんに似てる。"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "雑談・ヘロットについて"
  },
  Voice_5350_UnlockDesc = {
    Text = "覚醒体「ヘロット」獲得で解放"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "頭が冴えてきたわ、いい感じ。"
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5351_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "外勤より、実験室で仕事をする方が好きよ。まさか実験道具を海から引き上げたと思ってるの？"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5352_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "ネジでも釘でも、多ければ多いほど役に立つからね！"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "もうこの躯じゃ力を抑えきれないわ。でもまだ人形替えの時期じゃないし……突っ立ってないで手伝ってよ。調整するから、この足を持っていて。"
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5354_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "人々を光へと導くという使命は、ときに最も純粋な聖人すら押しつぶす重荷となります。白き炎よ、もし疲れを感じたら、私に話してください。あなたの苦痛を和らげるため、できる限りのことをいたしましょう。"
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "雑談・疲れについて"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "あなた様に認めていただけてこそ、僕は騎士で有り続けられるのです。"
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5356_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "神々の光が見えます、これがあなた様の持つ神通力ですか？なんという荘厳で神聖な光でしょう。"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5357_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "神の国に通ずる扉は、すぐそこに。"
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5358_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "より明るく、より鮮明に……"
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5359_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "覚醒体のまま人に戻れるなんて……ああ、聞こえる……神の国で奏でられる、わたくしのための聖なる歌が……"
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5360_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "神はわたくしを聖域に迎え入れ、安眠を与えてくださいました……"
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5361_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "私たち、絶対に役に立ちますから。私は裁縫や掃除が得意だし、もう一人の私は戦いが得意で、それから……"
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "明るくて柔らかいものが嫌い。優しさは鏡みたいに、私の醜さ、貪欲さ、そして弱さを映し出すから。"
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "ブラウンに触りたいのか？あたしに聞いても無駄だって、自分で聞いてみな。"
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "お前、この俺の気を惹こうとしているのか？だったら跪いて首を差し出せ。俺が飲み終わるまでは動くなよ？"
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5366_AwakerVoiceContent = {Text = "は！"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "昨夜、夢を見たのです。夢に出てきたのは、私の恒星間航行の始まりでした。"
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5367_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "あ、アイギスはお役に立てているのでしょうか。"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5368_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "感じちゃう♡"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5370_AwakerVoiceContent = {
    Text = "戦況を変えるわ！"
  },
  Voice_5370_AwakerVoiceTitle = {
    Text = "スキル・三"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "気をつけろ！"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "下がれ。"
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "誰も傷つかない世界が、生まれる。"
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5374_AwakerVoiceContent = {Text = "あん♡"},
  Voice_5374_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "主の祭壇を置くことを許可してください。これは信者によって彫られた彫像で、あなた様に呪いをもたらすことはないでしょう。"
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "ちょっとだけ……"
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "あたしのスパナはどこ！？"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "化学、物理学、シルバーコア応用学……この時代では「騎士七技」はもう時代遅れでしょうか。でしたら、僕にもこの世界の知識を学ばせてください！"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "オレッタは旅をしたことがあるの！波に流されるんじゃなくて、トレーラーでの旅だよ！"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5379_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "ベニクラゲ、カンムリクラゲ、マミズクラゲ、みんな群れで行動してるんだよ。オレッタもみんなと一緒がいいな！"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5380_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "昔のこと？あんまり覚えてないや……でも水族館で働いてたことは覚えてるよ！日給はたしか、2ペニーだったかな！"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5381_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "あのね、実はオレッタは海から来たの……つまりオレッタは海底人！オレッタがいい子にして、野菜をたくさん食べて、友達をいっぱい作れば、海のみんなが喜んでくれるんだ！"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5382_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "オレッタのおうち、水族館の仲間、大好きなクラゲたち、みんなみんな、いなくなっちゃった……あなたもいつかいなくなっちゃうの？……ずっとずっとオレッタと遊んでほしいな。"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5383_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "勝ったのか？よかった……"
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "平和のために。"
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "正義のために。"
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "君が僕の体内にいることは、知っている！"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "人間、偽神、覚醒体、融蝕……この世界のすべてが、わたくしが永遠の王国を再建するための礎となるでしょう。"
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "君が僕の体内にいることは、知っている！"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "ユウハシュは……お兄ちゃんと少し似てる。彼を見てると、冷たくて暗くて……ろくに眠れなかった昔の日々を思い出すの。"
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "雑談・ユウハシュについて"
  },
  Voice_5392_UnlockDesc = {
    Text = "覚醒体「ユウハシュ」獲得で解放"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "私たちの関係は……ホームズとワトソンに似ていると思わないかい？そういえば君、流行りの雑誌は読んだりするのかな？"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "美の虜になって。"
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "美の虜になって。"
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "「嫌い」形容動詞、嫌うこと。「嫌う」動詞、物事に強い反感を抱くこと。「反感」名詞、不愉快に思って逆らう気持ち。「不愉快」名詞、嫌な気持ち——<Del:抑えつけるな破壊させろ破壊させろ破壊>——すみません、嫌いの意味が分かりません。"
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "結局はこうなるのか……"
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "さらに変わったようだ。"
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "俺様はゴリアテだ！しっかり覚えとけよ。この名前は人類のちっぽけな歴史を塗り替えるぜ。"
  },
  Voice_5399_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5400_AwakerVoiceContent = {
    Text = "遠慮する必要はない。"
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "自分の才能と、寄せられた期待を裏切らないでね、新任守秘者。"
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "オーバーロード。"
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "オーバードライブ。"
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "財布の中の写真？ああ、それは昔の私だ。今のこの姿は、ギャンブル仲間でありライバルでもある、とある友人からの贈り物だ。"
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5404_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "おや、ちょうどいいとこに。暇なら私と賭けないかい？君が勝ったら秘密を一つ教えてあげよう。ああ、賭けのことはアルバには黙っておいておくれよ。"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5405_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "この毛皮が気になるのかい？なんなら触ってもかまわないよ？何、遠慮はいらないさ、私は懐が広いからね！"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5406_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "この体になってよかったこともある。それは、君というワトソンに出会えたことさ。そのラッキーに比べれば、命だの見た目だのは、大した問題じゃあない。むしろ感謝したいぐらいだ。"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5407_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "後悔してないかって？全然！順風満帆な人生なんて、つまらないだろう？"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5408_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "私の時代では、学校は戦士を鍛える場所だった。そういう意味では、今も昔も変わらないね。"
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "メイソン……いや、このままの方がいいよな。でも、こうしてまた一緒にいられて嬉しいよ「24」。"
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "雑談・「24」について"
  },
  Voice_5410_UnlockDesc = {
    Text = "覚醒体「24」獲得で解放"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "へへ、よくできたっしょ！そんじゃ報酬ちょーだい。言っとくけど、ただでお前を助ける義理なんてあたしにはないからな？"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "私はシディから来たわ。あそこでは誰もが注目されたいと思っていて、ただの観衆に甘んじる人なんていないの。でも本当は、私たちはあの街の飾りに過ぎないのかもね。"
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "雑談・過去について"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "古代の彫刻を見たことはある？とてもとても美しい作品なの。山に溶け込んでいるから、長い時間が経っても朽ちることはない……でも、私はそれじゃあ足りないの……"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "ハトが、帰ってこない……"
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "どきな！"
  },
  Voice_5415_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5416_AwakerVoiceContent = {Text = "ふん！"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "コマンド実行！"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5418_AwakerVoiceContent = {
    Text = "愚か者！"
  },
  Voice_5418_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "あれ？あたしを呼んでるの？バイクを修理してたから聞こえなかったよ……ねえ知らない人、あたしのスパナを見なかった？"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5419_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "いつも記憶があいまいで、目の前のことにしか専念できないんだ。でもできるだけ君の名前を覚えたくて……えっと、なんて名前だっけ？"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5420_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "君、優しそうな顔をしてるね。でも名前が思い出せないや……あたしの助手かなにか？それじゃ、ナットを七つ持ってきてくれる？"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5421_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "ファントムには君の名前を刻んだんだ。そうすればいつか一緒に冒険に出るとき、君の名前を忘れないからね。"
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5422_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "見覚えのある顔だ！あたしたちの間には、きっと何らかの関係があるはず！待ってて今思い出すから……あ、守秘者だよね！？"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5423_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "あなたって本当に素直じゃないわね……幸い、私には時間がたっぷりあるから、待ってあげる。私はとても辛抱強いのよ……？"
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "みんなが喜ぶかしら？"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "なかなか素敵なお首が手に入りましたわ。新しいコレクションを探す旅は、いつでも大歓迎です。今度もぜひ誘ってくださいね。"
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5427_AwakerVoiceContent = {
    Text = "ラ～……"
  },
  Voice_5427_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "プロのメイドが、ご主人様のために、悪人を含む汚いものをまるっと掃除しちゃいますよ～。"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "お前は仲間だかんな。いつかお前が路上で生きるはめになっても、ゴミを漁らなくてもいいように、あたしがしっかり面倒見てやるよ。"
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "苗木よ、大きく育ちなさい。"
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "苗木よ、大きく育ちなさい。"
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "よし！サイコロ運が上がった気がするよ！"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "よし、ついてる！"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "ラッキーじゃないか！"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "近寄んないで！"
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "近寄んないで！"
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "一つ言わせて、守秘者。あなたは優しすぎて、かえって不安になるの。私にとっては肉体の痛みだけが、永遠に残る真実なのに。"
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "いいね、褒めてやるよ。"
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "この程度じゃまだまだだよ。"
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "欲しいご褒美を言ってごらん？"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "チッ！まったく汚らしい場所だね。あたしの綺麗な足が汚れるじゃないか。そこの凡人、踏んでやるからあんたの柔らかい背中をお出し。"
  },
  Voice_5441_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5442_AwakerVoiceContent = {
    Text = "やっと……見つけた！"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "ブラウンまでスベスベだ。"
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5443_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "ボディガードはちょっと難しいけど、パシリなら任せて。"
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5444_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "ブラウン相手になんて顔するんだよ……？\nふふ、ブラウンさまが今晩臆病者の足を齧るって言ってるぞ。誰が選ばれるんだろうな？"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5445_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "背が伸びたりしないかな。"
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5446_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "仕事か？わかった、ブラウン、気合入れるぞ！"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5447_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "アグリッパ？悪いが、覚えていないな。何分殺した人間はわんさかいる身だ。弱い者ばかりで、記憶に残るほどの相手はなかなかいなくてな。"
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "雑談・アグリッパについて"
  },
  Voice_5448_UnlockDesc = {
    Text = "覚醒体「アグリッパ」獲得で解放"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "危険な乗組員ね……その、あくまでも航行の安全という観点からよ……"
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "雑談・ファロスについて"
  },
  Voice_5449_UnlockDesc = {
    Text = "覚醒体「ファロス」獲得で解放"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "来ないで！"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "き、気をつけてください！"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "やっつけたよ……あれ？またやりすぎたの？"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "わあ！ちょうど必要なパーツだ！くれるの？ありがとう！……え？あたしが探すのを手伝ってって言ったの？何にも覚えてないんだけど、記憶違いじゃない？"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "雑談・パーツについて"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "ふふ、閃きが次から次へと……"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "いいセンスしてるわね。"
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "このノミ、私の手にぴったりフィットするわ。あなたが選んでくれたのね。"
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "予想が外れるのは嫌いだね。けどまあ……あんたには気づかされたよ。多少の予想外は、一味違う楽しみにもなるってね。"
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "私、少しは成長できたでしょうか。"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "ごめんなさい、なかなか成長できなくて……"
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "これが世界を知る方法よ。"
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54602_AwakerVoiceContent = {
    Text = "これが世界を知る方法よ。"
  },
  Voice_54602_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54605_AwakerVoiceContent = {
    Text = "ごゆっくりお楽しみくださ～い！"
  },
  Voice_54605_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54606_AwakerVoiceContent = {
    Text = "ごゆっくりお楽しみくださ～い！"
  },
  Voice_54606_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54607_AwakerVoiceContent = {
    Text = "さあ、世界の本質を暴くわよ。"
  },
  Voice_54607_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54608_AwakerVoiceContent = {
    Text = "さあ、世界の本質を暴くわよ。"
  },
  Voice_54608_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54609_AwakerVoiceContent = {
    Text = "神のもとへ、帰るのです！"
  },
  Voice_54609_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_5460_AwakerVoiceContent = {
    Text = "ご、ご馳走様でした……"
  },
  Voice_5460_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_54610_AwakerVoiceContent = {
    Text = "神のもとへ、帰るのです！"
  },
  Voice_54610_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54611_AwakerVoiceContent = {
    Text = "邪魔をするな……！　アハハハ……ッ！"
  },
  Voice_54611_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54612_AwakerVoiceContent = {
    Text = "正義の光よ、深淵を照らせ！"
  },
  Voice_54612_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54613_AwakerVoiceContent = {
    Text = "邪魔をするな……！　アハハハ……ッ！"
  },
  Voice_54613_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54614_AwakerVoiceContent = {
    Text = "この甘い痛みに、酔いしれて！"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "この甘い痛みに、酔いしれて！"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "「おまえは死んだのだ、暗い流れに運ばれて！」"
  },
  Voice_54616_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54617_AwakerVoiceContent = {
    Text = "「おまえは死んだのだ、暗い流れに運ばれて！」"
  },
  Voice_54617_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54618_AwakerVoiceContent = {
    Text = "形無きものよ、守護の盾となれ！"
  },
  Voice_54618_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54619_AwakerVoiceContent = {
    Text = "形無きものよ、守護の盾となれ！"
  },
  Voice_54619_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_5461_AwakerVoiceContent = {
    Text = "ご心配いただいたこと、心より感謝いたします。"
  },
  Voice_5461_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5461_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_54620_AwakerVoiceContent = {
    Text = "深淵の獣よ、すべてを喰らい尽くせ！"
  },
  Voice_54620_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54621_AwakerVoiceContent = {
    Text = "深淵の獣よ、すべてを喰らい尽くせ！"
  },
  Voice_54621_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "正義の光よ、深淵を照らせ！"
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "我は束縛を解き放つ者、トクリ・リ！"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "我は束縛を解き放つ者、トクリ・リ！"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "この私は、未来を掴むために生まれた！"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "この私は、未来を掴むために生まれた！"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "わたくしの前に跪き、つま先に口づけなさい！"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "すべてのナットがここにある！"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "すべてのナットがここにある！"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "超越した力は深海の躯にしか宿らない。うらやましいだろう？まあ弱い人間に生まれたことはお前の罪じゃない。くよくよするな。"
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5462_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "わたくしの前に跪き、つま先に口づけなさい！"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "負けた奴らは、あたしの捕虜にしていいよね？"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5464_AwakerVoiceContent = {
    Text = "フンっ。"
  },
  Voice_5464_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "問題ない。"
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5466_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5467_AwakerVoiceContent = {Text = "あっ！"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "あのとき、あの者たちがすべてを溶かす呪いに苦しんでいたことを、私が知っていれば……私は必ず呪いを解き、すべての苦しみを取り除きます。たとえ再び命を失うことになろうとも。"
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "気を落とす必要はありません。海はすべての命を包み込んでくれます。"
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "そんな弱ぇ体じゃ、俺様の相棒として失格だ。学院のスポーツクラブへ行くぞ！ああ？お前の体を鍛えにだよ！"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "わたくしに力を貸してくれた可哀想な彼女は、今も融蝕に苦しんでいるの……なによ、その目は？彼女の居場所なら絶対に教えないから、諦めなさい！"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "運さえあれば、君だって向かうところ敵なしだ。"
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "より激しい愛を。"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "はぁ、ここのみんなは子どもがほとんどね。あの紳士は髪が真っ白だし、あのしかめっ面のお兄さんは片腕しかない、人選が難しいわね……困ったものだわ。"
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "ちょっと乱暴すぎるかしら？"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "丁寧に描かれた符文、信仰心のこもった神像、精錬を重ねた禁忌の薬……一つも欠けてはいけないの。"
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5476_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "深海で採掘した古代の青石で王座を作り、祭壇はもちろん、生贄の鮮血で塗りつぶして……何をぼんやりしているの？さっさと準備を進めてちょうだい。"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5477_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "あいつらを全員呼んできなさい。跪いて身を震わせながら、神の降臨を迎えるのが……あいつらにふさわしい最期だわ。"
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5478_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "深海にある遺跡へ向かい、神が生まれた場所の海水を浴びるの。"
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5479_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "降生の儀式へようこそ。ともに神の誕生を見届けましょう。……ちょっと、何を言っているの？神は滅びる運命……？そんな、そんなはずはないわ……！だって、あれほどの代償を払ったのに……"
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5480_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "我々はみな神の遺物です。"
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "これからは、貴方様のお側が、私とファイントの居場所になるのでしょうか？"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5482_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "そう、あのとき、私は声を失っていたのです。それを取り戻してくれたのは、貴方様の優しいお心です。"
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5483_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "神の戒めを愛せ。"
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "広大な星々、果てしない宇宙。終わりの見えない旅の中で、私は迷子になっていました。"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5485_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "手っ取り早くレベルを上げるのはいいけど、鍛錬は怠らないようにね。"
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "なるほど、こんな方法もあるのね……"
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "不思議な感覚ね。"
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "神の降臨は、この漆黒の死がもたらす苦難にピリオドを打つわ。そうでしょう？"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "おはようございます、主君。調査に出かけるのなら、僕がお供いたします。"
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5493_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "何をしてるの？くだらないいたずらはやめて、早く行動報告を済ませて。"
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "やっと始まるのかい？あたしの可愛いペットたちは、かなり飢えてるよ……"
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "血脈の力が漲ってくる。"
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "……待って、これ見たことあるわ。奴らが私に飲ませていた水に、この黒い粘液が混じっていたの。……私が「緑の炎」を手に入れたのは、それと関係があるのかしら？今となっては、禍転じて福と為す、って感じだけど。"
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "私はラモンナ･デクスター、ラモンナでいいわ。以後よろしくね、守秘者。"
  },
  Voice_5498_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5499_AwakerVoiceContent = {Text = "はい。"},
  Voice_5499_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5500_AwakerVoiceContent = {
    Text = "指令受理。"
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "ふん、不届き者ね、このわたくしが相手になってあげるわ。"
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "嫌いな物？そうだね……カラスの鳴き声と、馬車に乗りそびれることと、新しい靴を履いているときに限って雨が降ること。どれも縁起が悪いだろう？"
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "ダルスパナ、ライブスパナ、プラムスパナ、ワンウェイドライバー、プラスドライバー、皿小ネジ、なべ小ネジ……道具と修理パーツならなんでも好きだよ！"
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "あはは？バレちゃったあ？\n大丈夫だって、覚醒体は精神力がたっぷりあるから、意識のないお人形さんになるまでに、あと365回くらいは盗めるかな～。ええ～やっちゃダメなの？分かったよ、これからは控えておく！でも、腕や足を切り落とされる「恐怖」とかなら、ちょっぴり盗んでも構わないよね？"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5504_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "ねぇ君、カーシアのマジックのタネ、もう分かっちゃったんでしょ？しょうがないなぁ、それじゃあ秘密を守るために、ツアーに行くときは君にもついてきてもらわないとね。ははっ、感情を集めるためだろうって？やっぱり君にはかなわないね！"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5505_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "そこの君、カーシアの助手になってくれるかな？怖がらなくていいよ、このマジックボックスに入ってもらうだけだから。ちゃんと隠れた？じゃあ、剣を刺すね♪あ、そうそう、中には仕掛けとかないから♪"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5506_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "さあさあ～この帽子をかぶって！……そしたら～、プレゼントとして一番欲しいものを言ってみようか～。ふんふん、なるほどね、オッケ～。それじゃあ、帽子の中に手を入れてみて～♪"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5507_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "う～ん、困ったなぁ～。あの子たち毎回来てくれるから、マジックがもうすぐ底をついちゃうよ～。うん、マジシャンは同じ観客の前で同じトリックを披露しちゃいけないんだ。新しいマジックを考える？ごめん、そういう才能カーシアにはないんだよね。得意なのは真似事だけなんで。"
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5508_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "この学院でかろうじて見栄えがするのは、院長先生の休憩室くらいです。あなたはどう思いますか？"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5509_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "傲慢で卑劣なやつは、この手で始末する。"
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "復讐の刃を研ぎ澄ます。"
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "わたくしのサロンは舞踏会のような純粋なものではありません。覚悟はよろしいですか？"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5512_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "わたくしのサロンは、美しさとパワーが実る庭なのです……"
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5513_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "サロンにはシルクのクッション、紅茶にマカロン……そして朝露に濡れたバラが必要です。"
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5514_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "外部のゲストも学院に入れるよう、融通を利かせていただけませんか？"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5515_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "エラー、エラー、エラー、エラー……"
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "あっ！今何時ですか！すみませんご主人様……うっかり居眠りをしてしまいました……"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "このまま死を待つことしかできないの？ここから救い出してくれる人はいないの？……そんなことばかり考えていたけど、答えはずっと前からわかっていたわ。ただ認める勇気がなかっただけ……もしお前が現れなかったら、最後まで抗えなかったかもしれない。\nだ、だからありがとう……こ、告白とかじゃないから、勘違いしないでちょうだい！"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5518_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "あいつらの空虚な夢の中で、わたくしは生きていた。人生を選ぶ権利すら与えられないまま、わけのわからない予言のせいで、普通に生きることさえ叶わなくなった……あんな生活に戻らないためなら、なんでもするわ。"
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5519_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "「傷つけられた睡蓮たちは彼女をとりまき溜息します。\n彼女はときどき覚まします、睡っている榛の木の中の何かのねぐらをば、すると小さな羽ばたきがそこから逃れて出てゆきます。\n不思議な一つの歌声が金の星から堕ちてきます」\nああ、聞こえてしまいましたか？好きな文章の一節を朗読しているのです、あなたも一緒にどうですか？"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "雑談・読書について"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "淑女の部屋には勝手に入らない、淑女の格好にも口を出さない、わかったなら下がって、もう休むわ。"
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5521_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "わたくし相手に偉そうにしないことね。身の程を弁えなさい！真の主は誰なのか、目を凝らしてよ～く確認してみて。"
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5522_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "さあ、商品を並べましょうか？"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "やったな！ラム酒で勝利を祝おうぜ！"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "消えろ。"
  },
  Voice_5525_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5526_AwakerVoiceContent = {
    Text = "あたしに任せて。"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "このあたしに踏みにじられるのは、気持ちいいだろう？"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "我慢してね～♡"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "アイマスクの下が気になるのか？ふさわしいときが来れば、あなたにも見せてやろう。"
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "雑談・接触"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "もう終わり？興味が湧いてきたばっかりなのに。"
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "おいおい、俺をいじくるなよ。本物の戦士は自分の身ひとつで戦うもんだろ？"
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5531_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "アイギスは強くなりました……この目で、敵を動けないようにします！"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "一人一人が最前線で武器を磨き、戦いに備えているという点に関して、この大学は軍隊と何ら変わりない。"
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "パーフェクト！"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "パーフェクト！"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "俺に足枷を嵌めて、髪を掴んで跪かせても、奴隷にしてもいい。何も問題ねぇ――殺させてくれるならな。あの彫刻家を、提灯を、通りすがりの喘息持ちのババアを…………誰でもいい、奴らの喉を引き裂いて血を飲み干してやるって約束するぜ。"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5536_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "融蝕の傷口からは黒い粘液だけでなく、インスピレーションもたくさん湧いてくるの。正直に言うと、もっと傷が欲しいくらい。"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "怖いか！ははははは、それでいい！お前らの恐怖を味わわせてくれ！"
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5538_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "面白い、お前の血は蜂蜜酒のように甘いな。"
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5539_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "あのとき、偉そうなハゲ頭の首を折るや否や、数万人が喝采をあげて俺の名前を呼んだんだ。あのゾクゾクする感覚、俺の仲間であるお前なら、きっとわかってくれるだろう？"
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5540_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "きゃあっ！"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5542_AwakerVoiceContent = {
    Text = "いやぁ！"
  },
  Voice_5542_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5543_AwakerVoiceContent = {
    Text = "やぁ……！"
  },
  Voice_5543_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "くうっ！"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "広域アーカイブで「融蝕」を検索中……必要ない、かしこまりました。融蝕に対するエリカの考えを知りたい、かしこまりました。覚醒体のプライベートドメインで、「対融蝕兵器」を検索中……検索結果：「0」。"
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "贋作は煙や塵のようにもろく、わずかな風で吹き飛ばされてしまいます……"
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "雑談・マーフィーについて"
  },
  Voice_5546_UnlockDesc = {
    Text = "覚醒体「マーフィー」獲得で解放"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "なんだか騒がしいけど、学生かしら？\nああ……あのアホウドリに似た彼らね。あなたはアホウドリって知っている？その鳥はいつも元気いっぱいで、体力が尽きないみたいなの……"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5548_AwakerVoiceContent = {Text = "はっ！"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5549_AwakerVoiceContent = {Text = "ふん"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "学院のやつらは、剣術の才能があるラモンナを除けば、規則正しい者ばかりで面白みが足らん……まさかお前もその一員か？行動報告なぞ書いて楽しいのか？"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "造作もない。"
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "いろんなお母さんがいる。いいお母さんもいるし、悪いお母さんもいる。ご主人は、良いお母さん。"
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5552_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "主君を守りきれなかった僕に、どうか罰を……"
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "式場は予約できた？ガーデンは最低でも150ヤードは必要よ！"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5554_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "死にかけた人の血は、ドロドロしてるの。首をちょっと切れば、赤い線から暖かい血が溢れ出して、喉に流れ込んでくる……ふふ、おいしい。"
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "雑談・血液について"
  },
  Voice_5556_AwakerVoiceContent = {
    Text = "ていや！"
  },
  Voice_5556_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_5557_AwakerVoiceContent = {Text = "へい！"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_5558_AwakerVoiceContent = {Text = "ええ"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "慈悲深いあなた様は、私に居場所を与えてくれました。そんなあなた様に、私の不幸が移らないといいんですが……"
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "雑談・守秘者について"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "あたしは遥か遠くの星からやってきたんだ。吹雪が荒れ狂う極寒の地からね。なあに、凍えたことなんてないさ。あたしの屋敷には千人以上の下僕がいて、彼らの体温はとても暖かかったからね。"
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "雑談・過去について"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "ここで倒れるわけには参りません！"
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "ここで倒れるわけには参りません！"
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "「世界一の武器」を欲しがるなんて、本当に傲慢なお客様でした。その憎しみに満ちた首と交換で、と伝えたら、不満そうに帰っていきましたわ……"
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "雑談・ゴリアテについて"
  },
  Voice_5563_UnlockDesc = {
    Text = "覚醒体「ゴリアテ」獲得で解放"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "あなたのその、世界のためなら命も捧げられるって顔を見ていると、全身が痒くなるわ。"
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5564_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "研究禁止令が下る前に、あと少しで、この融蝕避難所を消すことができそうだったのに……とても残念だわ。"
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5565_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "ええ、バックアップの躰はいくらでもあった。融蝕から逃げ切るチャンスもね。でも、真理への扉が目前に開かれたとき、目を逸らせる学者はいないわ。わたしは心の声に応えただけ。後悔はない。"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5566_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "世界の真実、世界の始まり、世界の果て、すべてが無意味だわ。あなたが真実への道を歩みたいというなら、導いてあげても構わないわ……昔のようにね。"
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5567_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "わたしを止めても、終焉を止めることはできない……けれど、この大学とあなたは最後まで生かしておくわ。終焉のとき、高い塔の頂上から黄昏を眺めて、文明の崩壊を見届ける……それが、わたしとあなたの終わり方よ。"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5568_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "わかったわ。"
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "消えて。"
  },
  Voice_5570_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5571_AwakerVoiceContent = {
    Text = "わたくしの祈りが、祖国を呼び覚ます鐘の音になるとよいのですが……"
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "ティンクト以外に私を受け入れてくれる人がいるなんて、考えもしませんでした。\n守秘者さま、あなたに出会えて本当によかったです。この力を制御できるよう、頑張ります！そうすれば、あなたの精気を吸い取らずに、ハグが出来ます……ハグって、人間が感謝を表すときの方法ですよね？"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5572_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "何もしないで、ここにいていいんですか？\n……あの、私、人を脅すのが得意なんです。協力しなければ精気を吸い取るって言えば、みんな言うことを聞くから、以前ティンクトのためにもそうして……あっ！えっと、今のは妹には、内緒でお願いします！"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5573_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "ごめんなさい、私は他の人と違って、劣等品なんです……"
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5574_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "優秀なメイドはサロンに必要ですが、青緑色のメイドは……少し考えさせてください……"
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "雑談・カレンについて"
  },
  Voice_5575_UnlockDesc = {
    Text = "覚醒体「カレン」獲得で解放"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "ティンクトは双子の妹です。\nあの子は私と違って、いつもキラキラしていて……こんな姉さえいなければ、もっと輝かしい未来があったはずなんです……あの美しい歌声なら、全宇宙だって魅了できるのに……"
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5576_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "揺りかごの中は狭くて、体を伸ばすこともできません……でもティンクトに言われたんです、みんなの安全のために、揺りかごを離れたらダメだって……だから妹の言う通りにしています。"
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5577_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "わたくしは、生と死の狭間にいるような存在です。わたくしのそばでは、憂鬱が津波のように広がり、悲劇が絶え間なく訪れます。それでも、あなたの為に詩を詠んでもいいでしょうか？……そうですね、こういうときはもっと甘い言葉が相応しいのかもしれません……"
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5578_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "「薔薇はまだ咲かず、夜明けが来る」"
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5579_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "あなたは何を求めますか？美辞麗句？世界に誇れる名声？それとも、言葉の裏に隠された、血の通った本音ですか？"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5580_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "目に見えない墨で、いびつな蕾を描きます……この幽霊のように儚い薔薇は、詩のインスピレーションになるのです……"
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5581_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "従順たれ……！"
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "霊知覚醒・二"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "神の国に再生を！"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "霊知覚醒・三"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "あなたが希うのであれば、再び太陽の下を歩きましょう……シディにいた、あの頃のように……"
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5582_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "ふふん、宇宙の破滅をみたいかい？ええ～？違う～？ま、今更気が変わってももう遅いよ♪"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "霊知啓発・開花"
  },
  Voice_5583_UnlockDesc = {
    Text = "霊知啓発レベル15達成で解放"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "甘美な死を飲み干して。"
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "甘美な死を飲み干して。"
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "終わりよ！"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5587_AwakerVoiceContent = {
    Text = "やだ……"
  },
  Voice_5587_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "余の威光、とくと見るがよい。"
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "朝四時の空気はきれいね。一緒に体を鍛えてくれて嬉しいわ。彫刻って体力使うのよね。"
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "雑談・朝について"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "この力、なかなか使い勝手がいいね。"
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "霊知啓発・凝視"
  },
  Voice_5590_UnlockDesc = {
    Text = "霊知啓発レベル2達成で解放"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "対価を払わないお客様は嫌いです。商売を長くやっていると、必ずこの手のトラブルに遭遇しますわ。仕方ありませんので、私が直接、請求に伺うようにしています。"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "じっくり痛めつけてあげる～。"
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "じっくり痛めつけてあげる～。"
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5594_AwakerVoiceContent = {
    Text = "ロードします。"
  },
  Voice_5594_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5595_AwakerVoiceContent = {
    Text = "起動します。"
  },
  Voice_5595_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "一緒にここを賑やかな海にしようよ！"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "狂気解放"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "なに？わたくしの口からお礼の言葉が聞きたいの？"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "貢物としては不合格ね……でもまあ、せっかく準備してくれたんだし、受け取ってあげなくもないわ。"
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "こんなに貢いで、わたくしがあなたの思い通りになるとでも思ってるの？"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5600_AwakerVoiceContent = {
    Text = "はぁっ！"
  },
  Voice_5600_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5601_AwakerVoiceContent = {
    Text = "行っけ～！"
  },
  Voice_5601_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "恩知らずの化け物や、殺し屋まで認めるつもり？本当に変な人。"
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "霊知啓発・構築"
  },
  Voice_5602_UnlockDesc = {
    Text = "霊知啓発レベル11達成で解放"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "青金石の王座にどれほどクッションを敷いても、羽毛の寝床とは比べものにもならぬ。ことこれにおいては、貴様たちの文明を認めざるをえん。"
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "お仕置きだよ！"
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "スキル・一"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "一人ぼっちは、嫌……底のない暗闇の中で、ひとりで誰かを想い続けるのは、もう……ですからどうか、私を置いていかないと、約束していただけませんか？"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "あたしがお前なら、すべての覚醒体を檻に閉じ込めるわ！だって狂犬が檻から出たら、まず真っ先に主人が咬み殺されるでしょ？"
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "同調率・三"
  },
  Voice_5606_UnlockDesc = {
    Text = "同調率レベル6で解放"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "面会に一時間も遅れたわ……奴隷制を廃止しようって輩のせいで、あたしの髪をとかしてくれる人までいなくなったから！"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "同調率・二"
  },
  Voice_5607_UnlockDesc = {
    Text = "同調率レベル4で解放"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "信じられない、あたしの故郷……偉大なるローマが滅んだなんて……お前もローマぐらい知ってるでしょ！？"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "同調率・一"
  },
  Voice_5608_UnlockDesc = {
    Text = "同調率レベル2で解放"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "準備はいいかい？最初が肝心だよ！"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "これは主より賜った祝福です。"
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "そんな哀れむ目であたしを見るな！これ以上見つめられたら、お前をいたぶりたい衝動を抑えられなくなるわ……そんなの嫌なんでしょう？なら大人しくあたしの剣闘士でいて……"
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "同調率・五"
  },
  Voice_5611_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "この「*ピー*」、これ以上思い出させないで！あたしが油断したせいで、剣闘士に逃げられて、家族は殺されて、あたしの家はローマ帝国のように消滅したの！"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "同調率・四"
  },
  Voice_5612_UnlockDesc = {
    Text = "同調率レベル8で解放"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "学院の皆さんは才能溢れる方ばかりですが、私は手柄も取り手もない、至って平凡な人間です。\n私が覚醒したのは……まだ果たされない小さな願いがあるからかもしれません……"
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "今日また遅刻しちゃったの……校則を破った私に、一番重い罰を与えて！守秘者がしてくれると嬉しいんだけど……ふふ。"
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "道具もメンテが必要！良い道具はメカニックの魂だよ！"
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5615_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5616_AwakerVoiceContent = {Text = "くぅ！"},
  Voice_5616_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "今度また失敗したら、観察処分ね。"
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "戦闘以外は仕事はつまらぬが、自らの責務を果たすのは当たり前であろう？この星でもやるべきことはしっかりと……おい、まさか我のことを、喧嘩しか能がないと思っておったのか！？"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "雑談・仕事について"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "わたくしに近づく人はいつも、人生で一番悲しい体験を思い出し、涙を流します。こんなわたくしでも、成長していいのでしょうか？"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5619_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5621_AwakerVoiceContent = {Text = "こう？"},
  Voice_5621_AwakerVoiceTitle = {
    Text = "防御・二"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "ここはサイコーよ！汚くて臭い監獄よりずっといいわ！ソファに寝転んでも、壁にくっついても、ぜんぜん快適なの！"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "ブラウン！"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "さっき……何してたっけ？"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "ずるいぞ！"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "ナットはどこだ～！？"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "銀河の流れを……"
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "オレッタは突然いなくなる仲間が嫌い……でもでも、また戻ってくるなら許す！"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "一人で海を渡る女は、女神じゃなきゃただの馬鹿だな。……ミリアムを女神と勘違いするなんざ、俺もやきが回ったもんだ。"
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "雑談・ミリアムについて"
  },
  Voice_5629_UnlockDesc = {
    Text = "覚醒体「ミリアム」獲得で解放"
  },
  Voice_5630_AwakerVoiceContent = {Text = "うん！"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "カーシアさんのマジックショーを、こっそり見に行きました……彼女は、人々にたくさんの喜びを与えていて、悲しませてばかりのわたくしとは、大違いですね……え？……涙は笑顔と同じくらい大切、ですか？そうであれば、少し救われます……"
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "雑談・カーシアについて"
  },
  Voice_56313_UnlockDesc = {
    Text = "覚醒体「カーシア」獲得で解放"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "詩と炎と悲しみは、とても似ています。知らぬ間に飲み込まれ……気づけば、その世界から抜けだせなくなっている……"
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "雑談・好きなもの"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "想い出の詩が、心の庭を呼び覚ます。"
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "詩と花は、同じです。どちらも儚く、そして永遠に心に残るもの……この果てしない世界の中で、ほんの僅かな心の隙間に、詩と花は刻まれます。誰もがみな、一篇の詩に沈黙し、一輪の花に足を止め、心を打たれるのです。"
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "雑談・詩について"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "この季節のシディは、どんな花を咲かせるのでしょうか……？わたくしはもう、忘れてしまいました……"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "雑談・シディについて"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "あなたは、わたくしの筆から生まれた文字を、詩の世界に戻してくださいました。わたくしはこれから、あなたの物語を詠んでいきたいです。"
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "雑談・守秘者について1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "咲き誇る花は美しいですが、散る前の輝きであることが、悲しくてなりません。けれどわたくしは、どれだけ悲しくとも花のために足を止めましょう。悲しみを恐れて目を逸らせば、花が哀しみますから。"
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "雑談・苦痛について"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "エリカの休眠中に内部構造を研究したいというウインクルからの要求により、夜は彼女のオフィスで「眠って」います。実は「眠っている」間、意識の一部が保持されているということを、彼女に話すべきでしょうか？"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "雑談・ウインクルについて"
  },
  Voice_5631_UnlockDesc = {
    Text = "覚醒体「ウインクル」獲得で解放"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "マダム・レッドは美しいです。強さと自信、運命に立ち向かう優雅な微笑み、赤い薔薇のようにたくましい、あの力強く潔い生命力が、わたくしはうらやましいのです……"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "雑談・ソレールについて"
  },
  Voice_56320_UnlockDesc = {
    Text = "覚醒体「ソレール」獲得で解放"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "昨日、新しい詩を作りました。まだ誰にも見せていなくて……あまりいい詩ではないかもしれませんが、どうか読んでみてくれませんか……？"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "雑談・守秘者について2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "学生の詩人会から、指導者になってほしいと頼まれましたが……引き受けることはできませんでした。わたくしなどが指導者となっても、彼らに憂鬱と失望をもたらすだけですから……"
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "雑談・ミサゴ大学について"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "価値のないものなど、この世には存在しません。黄金時代の猛々しい詩も、晩年の憐れみを誘う詩も、どちらも心に響きます。華麗な装いには憧れが寄せられ、朽ち果てた古い布には、歴史が積もるのです。"
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "ニムフィーアさんに会うたびに、あの睡蓮の絵を思い出します。彼女には、睡蓮のような静けさと、苦く、清らかな香りを感じるのです……彼女の目に、世界はどう映っているのでしょう。"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "雑談・ニムフィーアについて"
  },
  Voice_56324_UnlockDesc = {
    Text = "覚醒体「ニムフィーア」獲得で解放"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "ずっと昔から、わたくしの周りには「幽霊」の気配がします。取り憑かれているのか……その存在は日ごとに、わたくしから世界への期待を失わせていくのです。けれど、もし本当に幽霊だとしたら、消えた牛乳やお水はどこへいったのでしょう……"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "雑談・幽霊について"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "わたくしの体は融蝕に浸食されてはおりません。この黒い液体は、ただの墨です。皆さんずいぶんと気になさっているようですが……融蝕があろうとなかろうと、すべてのものはいずれ無に帰る、そうですよね？"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "鍵塚の墓石に、守秘者の名を見ました……わたくしの生前の記憶は辛いものですが、忘れようと思ったことはありません。守秘者にとっても、失われた記憶はきっとかけがえのないものだと思うのです。"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "雑談・記憶について"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "もしも美を讃えるために詩が存在するのだとしたら、すべての詩人は彼女を語らずにはいられないでしょう。先人たちの言うナイチンゲールの歌声とは、彼女にこそ捧げられるべき言葉です。"
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "雑談・ティンクトについて"
  },
  Voice_56328_UnlockDesc = {
    Text = "覚醒体「ティンクト」獲得で解放"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "彼女のダンスは美しすぎて……たとえその体に纏う緑の炎に焼き尽くされようと、思わず触れたくなります……"
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "雑談・リッツについて"
  },
  Voice_56329_UnlockDesc = {
    Text = "覚醒体「リッツ」獲得で解放"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "原質を吸入する代わりに、こうするのですか？"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "美味しい、とても美味しいですわ。"
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "どのような報酬をお望みですか、お客様？"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "さっさと終わらせてかーえろ。"
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "鮮血を捧げましょう。"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "スキル・四"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "ううっ……"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "電流、準備完了。\n電流、発射。"
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "街一番の怪盗を見くびるな！"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "ショーの始まりだよ！みんな、拍手～！"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "この地に浮かべ、森羅幻象よ！"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "また、距離が縮んだ……"
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "霊知啓発・遠望"
  },
  Voice_5638_UnlockDesc = {
    Text = "霊知啓発レベル1達成で解放"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "堕ちろ、燃えろ、死ぬまで踊れ！"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "すべての彷徨う者よ、死の都へお行き。"
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "残りのエネルギーを……与えてあげる！"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "極限解放"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "街一番の怪盗を見くびるな！"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "極限解放・二"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "それは敵？敵なら、攻撃命令をください。\n黒い粘液は敵……じゃあ、リリーも敵なの？"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "トルソー番号EA307881、モーター番号MF311028、オートマタのエリカです。どうぞよろしくお願いいたします。"
  },
  Voice_5640_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5641_AwakerVoiceContent = {
    Text = "敵を徹底的に叩き潰すまで、全力で戦うぞ！"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "こんにちは、あたしは……あれ？あたしの名前を教えてくれない？"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "召喚"},
  Voice_5643_AwakerVoiceContent = {
    Text = "学院に来た後、ようやく自分がかかっていた融蝕という病気を知りました。生きていた頃、なぜ両親が私を海から遠ざけようとしたのか、やっとわかりました。私が海に親しみを感じていたのは、それが原因なのでしょうね……"
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "あなたをがっかりはさせないわ。"
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "調査開始"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "熱い吐息を感じて～！"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "狂気解放・二"
  },
  Voice_5646_AwakerVoiceContent = {
    Text = "行きなさい。"
  },
  Voice_5646_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5647_AwakerVoiceContent = {Text = "回れ。"},
  Voice_5647_AwakerVoiceTitle = {
    Text = "攻撃・二"
  },
  Voice_5648_AwakerVoiceContent = {
    Text = "アイギス、頑張ります！"
  },
  Voice_5648_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "ついにこの日がきたのですね……"
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5651_AwakerVoiceContent = {
    Text = "ご、ごめんなさい！"
  },
  Voice_5651_AwakerVoiceTitle = {
    Text = "攻撃・一"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "これじゃあ物足りないな……、なあ、もう一度殺させてくれないか？"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "後輩に忠告だ。我々は最終的な勝利を収めるまで、贅沢な生活を控えるべきだ。君も知っている通り、俺たちは貴族のために戦っているわけではない。"
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "雑談・ソレールについて"
  },
  Voice_5654_UnlockDesc = {
    Text = "覚醒体「ソレール」獲得で解放"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "捕虜になったら、どんなにひどい仕打ちを受けるか……ふふ……"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "調査中止"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "おりゃ！"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5657_AwakerVoiceContent = {
    Text = "僕は何も恐れない！"
  },
  Voice_5657_AwakerVoiceTitle = {
    Text = "防御・一"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "ふわぁ……退屈だったわ、ねぇ、リラックスできるハーブティーは用意できたの？"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "調査成功"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "お母さん、触ってみる？とても柔らかい、評判。"
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "霊知啓発・会得"
  },
  Voice_5659_UnlockDesc = {
    Text = "霊知啓発レベル7達成で解放"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "ラララ～ラララ～♪　お掃除大好き、すっきりきれいで、いい気分～♪"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "雑談・仕事について"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "はぁ、はぁ……"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "被ダメージ・四"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "はぁあ、いいよぉ……"
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "被ダメージ・一"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "はぁ、はぁ……"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "被ダメージ・二"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "はぁ、はぁ……"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "被ダメージ・三"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "燃え盛る怒りよ！"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "特殊スキル・一"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "融蝕のせいで頭がいかれた奴は少なくない。でも俺はとっくにいかれてるからな、影響は少ないだろう。"
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "雑談・融蝕について"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "血に溶けなさい。"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "良い道具を持てば、戦いは半分勝ったことになるよ！"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "生き返るな。"
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "昇格・三"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "ほほう、なかなかやるではないか。"
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "昇格・二"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "より強い一撃が出せるな。"
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "出勤率を保ちつつ、研究も新人の教育もやらないと……どうやら時間圧縮のリバース実験をする必要があるようね。"
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "霊知啓発・深思"
  },
  Voice_5672_UnlockDesc = {
    Text = "霊知啓発レベル3達成で解放"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "冒険まであと一歩。"
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "昇格・一"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "水からあたしを守って！あんたへの愛の火が、消えちゃうでしょ？"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "雑談・嫌いなもの"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "戦い抜くぞ！"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "この触手たちが怖くはないの？お前を吞み込もうとしてるのに。まあ、その勇気は褒めてあげるわ。"
