  },
  Voice_5774_AwakerVoiceTitle = {
    Text = "霊知覚醒"
  },
  Voice_5775_AwakerVoiceContent = {
    Text = "ラジャー。"
  },
  Voice_5775_AwakerVoiceTitle = {
    Text = "スキル・二"
  },
  Voice_5776_AwakerVoiceContent = {Text = "ちっ！"},
  Voice_5776_AwakerVoiceTitle = {
